'Cr_Guide_T_Statuses' => 'Statusser',
'Cr_Guide_Statuses_Note' => 'Statusser bevæger sig kun fremad, så en sen opdatering trækker aldrig en pakke tilbage. En leveret pakke kan stadig meldes som på vej retur eller returneret.',
