'Cr_Guide_S_returning' => 'På vej tilbage til dig.',
'Cr_Guide_S_returned' => 'Tilbage hos dig: den venter under Returer til gennemgang, eller lægges automatisk på lager igen.',
'Cr_Guide_S_cancelled' => 'Bestillingen blev annulleret.',
'Cr_Guide_T_Booking' => 'Bestilling af ordrer',
'Cr_Guide_B_Booking' => 'Send til kurer udfylder formularen ud fra salget: modtager, adresse, det udestående beløb som efterkrav og produkternes vægt. Kurerer med egne bylister viser en vælger, og dit valg huskes for den by. Aggregatorer, DHL, FedEx, UPS og Lalamove tilbyder Sammenlign priser: vælg en pris, og Bestil køber den. Flere salg kan bestilles på én gang fra salgslisten.',
'Cr_Guide_T_Cod' => 'Efterkrav',
'Cr_Guide_B_Cod' => 'En efterkravspakke går fra Ikke opkrævet til Opkrævet af kurer (ved levering) til Udbetalt til dig. Kurerer, der rapporterer udbetalinger, flytter selv det sidste trin; for de øvrige bruges Opdater efterkrav. Med en konto valgt i Kurerindstillinger registreres en udbetaling som en betaling på salget. Kurergebyrer kan gemmes som en udgift, når en pakke er afsluttet.',
'Cr_Guide_T_Returns' => 'Returnerede pakker',
'Cr_Guide_B_Returns' => 'Som standard venter en returneret pakke i Kurerforsendelser under Returer til gennemgang. Læg på lager opretter en salgsretur for hele ordren og lægger varerne tilbage på lager; Afvis lægger intet tilbage – til beskadigede eller bortkomne pakker. Kurerindstillinger kan i stedet lægge på lager automatisk.',
'Cr_Guide_T_Customers' => 'Kundebeskeder og sporingsside',
'Cr_Guide_B_Customers' => 'Kundenotifikationer i Kurerindstillinger sender SMS, e-mail eller WhatsApp ved de statusser, du markerer – hver én gang pr. pakke og med din egen tekst. Sporingssiden i din onlinebutik lader kunderne følge en pakke via sporingsnummer eller via ordrenummer og telefon. Kunder, der ofte returnerer pakker, får et returrisiko-mærke, når du bestiller.',
'Cr_Guide_T_Labels' => 'Pakkelabels',
'Cr_Guide_B_Labels' => 'Udskriv label giver kurerens egen label, når den udsteder en (en PDF, et link eller et billede), ellers en Stocky-label med sporingsstregkoden og beløbet, der skal opkræves. Tillad pop op-vinduer for dette websted for at udskrive. DHL, FedEx og UPS udleverer kun deres label én gang, ved bestilling, og Stocky gemmer den til genudskrivning.',
'Cr_Guide_T_Faq' => 'Fejlfinding',
'Cr_Guide_Q_Test' => 'Test forbindelse fejler',
'Cr_Guide_A_Test' => 'Testnøgler hører til Testtilstand og live-nøgler til Live; de er forskellige. Åbn Kurerlog, og læs kurerens svar for at se den præcise årsag.',
'Cr_Guide_Q_City' => 'Kureren afviser byen eller adressen',
'Cr_Guide_A_City' => 'Vælg byen fra kurerens byliste i bestillingsformularen; kurerer accepterer kun deres egne navne. Kurerer, der arbejder med postadresser, skal også have region, postnummer og landekode på to bogstaver.',
'Cr_Guide_Q_Webhook' => 'Statusser ændres ikke af sig selv',
'Cr_Guide_A_Webhook' => 'For kurerer, der sender opdateringer, skal du kontrollere, at webhook-URL\'en er registreret hos kureren: Kurerlog viser alle modtagne opdateringer, eller hvorfor en blev afvist (f.eks. en forkert hemmelighed). Andre kurerer tjekkes efter tidsplanen i Kurerindstillinger, og Tjek status nu spørger med det samme.',
'Cr_Guide_Q_Stuck' => 'En forsendelse viser en fejl ved statustjek',
'Cr_Guide_A_Stuck' => 'Kureren afviste de seneste tjek; årsagen står på forsendelsen og i Kurerlog. Efter gentagne fejl tjekkes en forsendelse ikke længere automatisk: ret årsagen, og brug derefter Tjek status nu.',
'Cr_Guide_Q_Label' => 'Intet åbner, når en label udskrives',
'Cr_Guide_A_Label' => 'Din browser blokerede pop op-vinduet. Tillad pop op-vinduer for dette websted, og prøv igen.',
'Cr_Guide_Q_Cod' => 'En efterkravsudbetaling blev ikke registreret på salget',
'Cr_Guide_A_Cod' => 'I Kurerindstillinger kræver efterkrav, at kontakten er slået til, og at en konto er valgt. Uden en konto markeres udbetalinger kun som udbetalt.',
