'Restrict_Master_Data_By_Warehouse' => 'Begræns stamdata efter lager',
'Restrict_Master_Data_By_Warehouse_Help' => 'Når den er slået til, ser en bruger, der er tildelt bestemte lagre, kun de produkter, kunder, leverandører, mærker og kategorier, der er knyttet til disse lagre. Poster, der endnu ikke er brugt nogen steder, forbliver synlige, så nyoprettede aldrig skjules. Salg, køb og returer er altid begrænset og påvirkes ikke af denne kontakt.',
'Restrict_Products_By_Warehouse' => 'Begræns produkter efter lager',
'Restrict_Products_By_Warehouse_Help' => 'Hvert produkt får et hjemmelager – den filial, det blev oprettet til. Når den er slået til, ser, sælger og redigerer en bruger, der er tildelt bestemte lagre, kun de produkter, hvis hjemmelager er brugerens, samt produkter med faktisk lagerbeholdning på et af brugerens lagre (overført eller indkøbt dertil). Brugere med adgang til alle lagre ser altid alt. Onlinebutikken følger samme regel: den viser kun produkterne fra de lagre, der er valgt i Butiksindstillinger.',
'Virtual_Combo_Stock' => 'Virtuel kombilagerbeholdning',
'Virtual_Combo_Stock_Help' => 'Når den er slået til, har et kombiprodukt ingen egen lagerbeholdning: tilgængeligheden er det antal kombier, dets komponentprodukter stadig kan dække, og salg af en kombi trækker lager fra komponenterne. Når den er slået fra, samles kombier først på lager med en Justering.',
'Virtual_Combo_Stock_Warning' => 'Vælges bedst, før der sælges kombier. Når kombier er solgt eller returneret, vil et skift få senere redigeringer, sletninger og returneringer af disse dokumenter til at tilbageføre lageret forkert.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'Slå virtuel kombilagerbeholdning til?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Kombier sælges direkte fra deres komponentprodukter, og deres egen lagerbeholdning bruges ikke længere.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'Slå virtuel kombilagerbeholdning fra?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Kombier går tilbage til deres egen lagerbeholdning, som skal samles af komponenterne med en Justering, før de kan sælges.',
'Home_Warehouse' => 'Hjemmelager',
'Home_Warehouse_Hint' => 'Den filial, produktet hører til. Brugere, der er begrænset til andre lagre, ser det ikke, medmindre der overføres lager til dem.',
