'Tg_Guide_A_Title' => 'Med det samme – intet at installere',
'Tg_Guide_A_Body' => 'Et salg, køb, en betaling eller en udgift, der gemmes i Stocky – i POS eller i administrationen – sendes til Telegram {rightAfter} det er gemt, i samme forespørgsel. Ingen cron-post, ingen køarbejder, og kassereren venter aldrig på Telegram: salget er allerede besvaret, når beskeden sendes.',
