'Tg_Guide_B_Title' => 'Cron-posten – til genforsøg og baggrundshændelser',
'Tg_Guide_B_Body' => 'To slags beskeder venter i stedet i Telegrams egen kø: en afsendelse, der fejlede (Telegram var kortvarigt utilgængelig), som forsøges op til tre gange mere i løbet af de næste minutter; og hændelser udløst uden for administrationen – ordrer importeret fra WooCommerce eller Shopify, artisan-kommandoer. Denne cron-post sender dem, og intet andet:',
'Tg_Guide_B_Note' => 'Hvert minut er det rigtige: en kørsel uden noget i kø afslutter med det samme. På cPanel lægges dette under {cronJobs} – brug den fulde sti til PHP 8.2+, hvis {php} er ældre. På Windows bruges Opgavestyring med programmet {php2}, argumenterne {args} og startmappen {path}.',
'Tg_Guide_N_Waiting' => '{n} venter på at blive sendt',
'Tg_Guide_Nothing_Waiting' => 'intet i kø',
'Tg_Guide_N_Gave_Up' => '{n} opgivet efter genforsøg',
'Tg_Guide_Growing_Hint' => '– hvis tallet bliver ved med at stige, kører cron-posten ikke.',
'Tg_Guide_Without_Cron' => 'Uden cron-posten ankommer alt, der gemmes i Stocky, stadig med det samme; du mister kun genforsøgene og de importerede ordrer.',
'Tg_Guide_Else_Title' => 'Alt andet',
'Tg_Guide_Else_Body' => 'Beskeder for hændelser udløst i baggrunden leveres af platformen – der er intet at sætte op.',
'Tg_Guide_Not_Arrive' => 'Hvis den ikke kommer frem',
'Tg_Guide_Err_401' => '{code} — bot-tokenet er forkert. Indsæt det igen fra BotFather.',
'Tg_Guide_Err_400' => '{code} — forkert chat-ID, eller botten er ikke med i gruppen. Ved en personlig chat skal du først skrive til botten.',
'Tg_Guide_Err_403' => '{code} — tilføj botten til gruppen igen, eller som administrator af kanalen.',
'Tg_Guide_Test_Works' => 'Testen virker, men salg kommer ikke igennem',
'Tg_Guide_Test_Works_Item' => '{label} — tjek, at hændelsen er markeret (eller at {allEvents} er valgt), og at kontakten er slået til.',
'Tg_Guide_Imported_Never' => 'Importerede ordrer kommer aldrig',
'Tg_Guide_Imported_Never_Item' => '{label} — cron-jobbet ovenfor kører ikke.',
'Jumia_Hero_Title' => 'Synkronisering med Jumia-markedspladsen',
'Jumia_Hero_Desc' => 'Send priser og lager til dine opslag i Jumia Seller Center, og importér ordrer fra markedspladsen som salg.',
'Jumia_Api_Url_Label' => 'API-URL (dit lands Seller Center-endpoint)',
'Jumia_Account_Email' => 'Konto-e-mail (bruger-ID)',
'Jumia_Prices_Stock' => 'Priser & lager',
'Jumia_Push_Card_Title' => 'Send priser & lager til Jumia',
'Jumia_Push_Desc' => 'Sender den aktuelle pris og mængde for hvert produkt (og hver variant), hvis SKU matcher Jumia-opslagets {sellerSku}. Opdateringer indsendes som Seller Center-feeds og anvendes asynkront — feed-ID’et registreres på fanen Logfiler, og afvisninger pr. vare vises på feedstatus-skærmen i Seller Center.',
'Jumia_Push_Prices_Stock' => 'Send priser & lager',
'Jumia_Orders_Desc' => 'Importerer ordrer fra markedspladsen som salg (referencer som {ref}), matchet til dine produkter via Seller SKU. Allerede importerede og annullerede ordrer springes over, så det er sikkert at hente jævnligt. Betalinger markeres kun som betalt for leverede ordrer (på Jumia betales der overvejende ved levering/COD).',
'Jumia_Guide_1' => 'I Jumia {sellerCenter} skal du åbne Settings → {integrationMgmt} og generere en API-nøgle.',
'Jumia_Guide_2' => 'Indtast dit lands API-URL (f.eks. {ng} for Nigeria, {ke} for Kenya, {eg} for Egypten), e-mailen til din Seller Center-konto og nøglen — kør derefter {test}.',
'Jumia_Guide_3' => 'Sørg for, at hvert Jumia-opslags {sellerSku} er lig med Stocky-produktkoden — det er den identitet, der bruges både til lageropdateringer og ordrematchning.',
'Jumia_Guide_4' => 'Send priser & lager efter lagerændringer; hent ordrer jævnligt (Jumia har ingen webhooks i denne API).',
'Jumia_Guide_5' => 'Oprettelse af nye opslag foregår fortsat i Seller Center — Jumia kræver kategorispecifikke attributter og billedgodkendelse, som kun deres portal håndterer godt.',
'Mc_Hero_Title' => 'Synkronisering af Mailchimp-målgruppe',
'Mc_Hero_Desc' => 'Hold en Mailchimp-målgruppe fyldt med dine kunder, så du kan køre e-mailkampagner på din reelle kundebase.',
'Mc_Account_Audience' => 'Konto & målgruppe',
'Mc_Api_Key_Placeholder' => 'f.eks. a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Målgruppe',
'Mc_N_Members' => '({n} medlemmer)',
'Mc_Load_Audiences_To_Pick' => 'Indlæs målgrupper for at vælge en',
'Mc_Load_Audiences' => 'Indlæs målgrupper',
'Mc_Double_Opt_In_Label' => 'Dobbelt opt-in — nye medlemmer får en bekræftelsesmail, før de tilmeldes',
'Mc_Recommended_GDPR' => '(anbefales af hensyn til GDPR)',
'Mc_Auto_Sync_New' => 'Synkronisér nye kunder automatisk, når de oprettes',
'Mc_With_Email' => 'Med e-mail',
'Mc_Push_Desc' => 'Opretter eller opdaterer alle kunder med en e-mailadresse i den valgte målgruppe (inkl. navn og telefon). Eksisterende medlemmer beholder deres abonnementsstatus — ingen, der har afmeldt sig, tilmeldes igen. Kunder uden e-mail udelades.',
'Mc_Double_Opt_In_Off' => 'Dobbelt opt-in er slået fra',
'Mc_Double_Opt_In_Off_Desc' => 'Nye medlemmer tilføjes som tilmeldt uden bekræftelsesmail. Gør kun dette for kunder, der allerede har givet samtykke til at modtage markedsføring.',
'Mc_Guide_1' => 'Åbn {path} i Mailchimp, og opret en nøgle (den slutter på {suffix} — det suffiks er dit datacenter).',
'Mc_Guide_2' => 'Indsæt nøglen her, gem, klik derefter på {load}, og vælg den målgruppe, der skal fyldes.',
'Mc_Guide_3' => 'Lad {doi} være slået til, medmindre dine kunder allerede har givet samtykke til markedsføringsmails.',
'Mc_Double_Opt_In_Lower' => 'dobbelt opt-in',
'Mc_Guide_4' => 'Kør {push} til den første fyldning; slå {autoSync} til, så nye kunder kommer med automatisk.',
'Mc_Auto_Sync_Lower' => 'automatisk synkronisering',
'Mc_Consent_Matters' => 'Samtykke er vigtigt',
'Mc_Consent_Desc' => 'At sende e-mails til personer, der aldrig har givet samtykke til markedsføring, kan overtræde GDPR/CAN-SPAM og få din Mailchimp-konto suspenderet. Dobbelt opt-in flytter bekræftelsen over til Mailchimp — det sikre standardvalg.',
'Mc_No_Audiences' => 'Der blev ikke fundet nogen målgrupper på denne konto.',
'Presta_Hero_Desc' => 'Synkronisér produkter, lager og ordrer med din PrestaShop-butik via dens webservice-API.',
'Presta_Webservice_Key' => 'Webservice-nøgle',
'Presta_Key_Placeholder' => 'Fra Advanced Parameters → Webservice',
'Presta_Key_Help' => 'Aktivér webservicen i PrestaShop (Advanced Parameters → Webservice), opret en nøgle med rettigheder til products, stock_availables, orders og customers, og indsæt den her. Gemmes skrivebeskyttet (vises aldrig igen).',
'Presta_Shop_Language_ID' => 'Butikkens sprog-ID',
'Presta_Language_Help' => 'Sprog-ID, der bruges til produktnavne ved afsendelse (1 = butikkens første sprog).',
'Presta_Push_Desc' => 'Opretter manglende simple produkter i PrestaShop (med deres aktuelle lager). Allerede tilknyttede produkter og variantprodukter springes over — redigér fortsat produktdetaljer i PrestaShop, eller hent for at opdatere den lokale kopi.',
'Presta_Pull_Desc' => 'Importerer PrestaShop-produkter, matcher eksisterende via reference (SKU) og opretter resten. Kombinationer importeres som deres overordnede produkt.',
'Presta_Reset_Confirm' => 'Nulstil produkttilknytninger? Ordrehistorikken beholder sine tilknytninger.',
'Presta_Stock_Desc' => 'Opdaterer butikkens lager (stock_availables) for alle tilknyttede produkter.',
'Presta_Orders_Desc' => 'Importerer butiksordrer som salg (referencer som {ref}), nyeste først. Allerede importerede og annullerede ordrer springes over, så det er sikkert at hente jævnligt. PrestaShop har ingen webhooks — kør dette efter travle perioder.',
'Presta_Guide_1' => 'Åbn {path} i din PrestaShop-administration, og aktivér webservicen.',
'Presta_Guide_2' => 'Tilføj en ny nøgle, og giv {vae} på {products} og {stock} samt {view} på {orders} og {customers}.',
'Presta_Guide_3' => 'Indsæt butikkens URL og nøglen på fanen Forbindelse, gem, og kør {test}.',
'Presta_Guide_4' => 'Hent produkter først, hvis butikken allerede har et katalog (matcher via reference/SKU); send for at oprette manglende simple produkter.',
'Presta_Guide_5' => 'Send lager, hver gang mængder ændres, og hent ordrer jævnligt — PrestaShop har ingen webhooks, så ordrer kommer kun, når du henter.',
'Presta_Identity_Title' => 'Produktidentiteten er referencen (SKU)',
'Presta_Identity_Desc' => 'Stockys produktkode matches med PrestaShops reference. Hold referencerne ens på begge sider; kombinationer (varianter) matches i ordrer via reference, men sendes ikke i denne version.',
