'Fbr_Guide_What_Title' => 'Hvad er FBR digital fakturering?',
'Fbr_Guide_What_Body' => 'I henhold til SRO 69(I)/2025 kræver Federal Board of Revenue (Pakistan), at integrerede virksomheder indberetter salgsfakturaer elektronisk i realtid via PRAL Digital Invoicing (DI) API\'et. Hvert godkendt salg får et officielt FBR-fakturanummer, og kvitteringer skal vise dette nummer sammen med en QR-kode til verifikation.',
'Fbr_Guide_Steps_Title' => 'Trin til at gå live',
'Fbr_Guide_Step_1' => 'Registrér dig på FBR IRIS-e-faktureringsportalen, og hent et {sandbox}-sikkerhedstoken.',
