'Fbr_Guide_Step_3' => 'Foretag testsalg, der dækker de scenarier, FBR har tildelt dig (vælg scenariet i feltet Sandbox-scenarie). Tjek fanen Dokumenter for at bekræfte, at de kommer retur som {valid}.',
'Fbr_Guide_Step_4' => 'Når FBR har godkendt din sandbox-test, henter du {production}-tokenet fra portalen, indsætter det her og skifter miljøet til {production}.',
'Fbr_Guide_Step_5' => 'Kvitteringer viser automatisk FBR-fakturanummeret og QR-koden, når et salg er godkendt — der kræves ingen ekstra trin ved kassen.',
