'Woo_Automatic_Sync' => 'Automatisk synkronisering',
'Woo_Auto_Sync_Intro' => 'Send ændringer foretaget i Stocky til WooCommerce, efterhånden som de sker, uden at åbne denne side. Hver overførsel kører lige efter, at handlingen er gemt, så kassemedarbejderen aldrig skal vente på WooCommerce. Resultaterne vises på fanen Logfiler.',
'Woo_Auto_Sync_Products_Help' => 'Et produkt, der oprettes, redigeres eller duplikeres i Stocky, sendes til WooCommerce (detaljer, pris, varianter, billeder, lager). Masseimporter sendes ikke; efter en import skal du bruge Synkronisér — POS → WooCommerce på fanen Produkter.',
'Woo_Auto_Sync_Stock_Help' => 'Enhver lagerbevægelse (POS-salg, salg, retur, køb, justering, overførsel) opdaterer antallet af de berørte produkter på WooCommerce. Kun produkter, der allerede er tilknyttet WooCommerce, opdateres.',
'Woo_Sync_Tuning' => 'Finjustering af synkronisering',
'Woo_Sync_Tuning_Intro' => 'Standardværdierne passer til de fleste butikker. Ændr dem kun, hvis synkroniseringen er langsom eller får timeout hos din hostingudbyder. Alle værdier er begrænset til et sikkert interval, og hvis du rydder et felt, gendannes standardværdien.',
'Woo_Sync_Guide' => 'Guide til WooCommerce-synkronisering',
'Woo_Guide_Getting_Keys' => 'Sådan får du API-nøgler',
'Woo_Guide_Keys_1' => 'I WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Klik på Add key, vælg Read/Write, og kopiér derefter Consumer key og Consumer secret.',
'Woo_Guide_Keys_3' => 'Butiks-URL: dit websteds URL uden afsluttende skråstreg (f.eks. {example}).',
'Woo_Guide_WP_Title' => 'WP-brugernavn og applikationsadgangskode (valgfrit)',
'Woo_Guide_WP_Intro' => 'Disse felter bruges kun til produktbilleder. WooCommerce-API\'et (butiks-URL + Consumer key/secret) står for synkronisering af produkter, lager, kategorier, mærker, kunder og ordrer; WordPress REST API\'et står for mediebiblioteket (søgning efter og upload af billeder).',
'Woo_Guide_WP_1' => 'Ved synkronisering af produkter eller lager kan Stocky vedhæfte produktbilleder: Den søger først i WordPress-mediebiblioteket efter et eksisterende billede ud fra filnavnet; findes det ikke, uploader den billedet via WordPress-API\'et.',
'Woo_Guide_WP_2' => 'Brug en WordPress-bruger, der kan administrere medier (f.eks. Administrator). Opret en applikationsadgangskode i WordPress: Users → Profile (eller din bruger) → Application Passwords — tilføj en ny, og indsæt den her.',
'Woo_Guide_WP_3' => 'Hvis du lader disse felter stå tomme, fungerer synkroniseringen stadig for alle data (produkter, lager, kategorier, mærker, kunder, ordrer); kun vedhæftning af produktbilleder (søgning/upload) springes over.',
'Woo_Guide_How_To_Enable' => 'Sådan aktiverer du det',
'Woo_Guide_Enable_1' => 'Indtast butiks-URL, Consumer key og Consumer secret ovenfor, og klik derefter på Gem.',
'Woo_Guide_Enable_2' => 'Brug Test forbindelse til at bekræfte loginoplysningerne.',
'Woo_Guide_Enable_3' => 'Brug manuel synkronisering fra en hvilken som helst fane, når du har brug for at synkronisere.',
'Woo_Guide_Enable_4' => 'Slå Automatisk synkronisering til ovenfor for at sende nye og redigerede produkter samt alle lagerændringer til WooCommerce, efterhånden som de sker.',
'Woo_Guide_Manual_Sync' => 'Manuel synkronisering (efter behov)',
'Woo_Guide_Manual_1' => 'Synkronisering fungerer i begge retninger: Stocky → WooCommerce og WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'Manuel synkronisering er tilgængelig på alle WooCommerce-faner (Produkter, Lager osv.); brug synkroniseringshandlingerne på hver fane til at synkronisere efter behov.',
'Woo_Guide_Auto_1' => 'Produkter: Når det er slået til, sendes et produkt, du opretter, redigerer eller duplikerer i Stocky, til WooCommerce lige efter, at du har gemt det, efterfulgt af dets lager.',
'Woo_Guide_Auto_2' => 'Lager: Når det er slået til, opdaterer hver lagerændring (POS-salg, salg, retur, køb, justering, overførsel) antallet på WooCommerce. Kun produkter, der allerede er tilknyttet WooCommerce, opdateres.',
'Woo_Guide_Auto_3' => 'Automatisk synkronisering sender kun ændringer fra Stocky til WooCommerce. Data fra WooCommerce (ordrer, kunder, produkter) hentes altid ind i Stocky med knapperne på fanerne Ordrer, Kunder og Produkter.',
'Woo_Guide_Auto_4' => 'Masseimporter af produkter sendes ikke automatisk. Efter en import skal du bruge Synkronisér — POS → WooCommerce på fanen Produkter.',
'Woo_Guide_Auto_5' => 'Hver automatisk overførsel registreres på fanen Logfiler, så du kan se, hvad der blev sendt, og finde fejl.',
'Woo_Guide_First_Setup' => 'Første opsætning',
'Woo_Guide_First_1' => 'Kør disse én gang i denne rækkefølge, så dit eksisterende katalog bliver tilknyttet: Synkronisér — POS → WooCommerce på fanen Kategorier, derefter fanen Mærke, derefter fanen Produkter og til sidst Synkronisér lager på fanen Lager. Slå derefter Automatisk synkronisering til ovenfor for at holde WooCommerce opdateret.',
'Woo_Guide_First_2' => 'Store produkt- og lagersynkroniseringer kører i små portioner og viser deres fremskridt på fanen. Hold siden åben, indtil synkroniseringen er færdig; du kan stoppe den når som helst.',
'Woo_Guide_First_3' => 'Hvis en synkronisering står stille i flere minutter, så tjek fanen Logfiler, og kontakt derefter support.',
'Woo_Guide_Notes_1' => 'Hvis du ændrer butiks-URL eller API-nøgler, nulstilles tilknytningerne (produkter, kategorier, mærker, kunder); elementerne synkroniseres igen til den (nye) butik.',
'Woo_Guide_Notes_2' => 'Hold SKU\'er ens i Stocky og WooCommerce for at undgå dublerede produkter og for at kunne gentilknytte sikkert.',
