'Pg_Store_Feature_Not_In_Plan' => 'Gateways til onlinebutikken og offline-betalingsmetoder er en del af funktionen Online-ordrer, som din nuværende plan ikke omfatter.',
'Pg_Intro_Title' => 'Alle gateways her tilbydes ved ONLINEBUTIKKENS checkout, når deres loginoplysninger er gemt, og kontakten er slået til.',
'Pg_Intro_Desc' => 'Hver fane har sin egen til/fra-kontakt, som gemmes i det øjeblik, du slår den om: Når en gateway slås fra, bevares dens loginoplysninger, og checkout holder blot op med at tilbyde den. Stripe-nøgler deles globalt (administration og onlinebutik bruger den samme Stripe-integration). Offline-betalinger omfatter efterkrav og mobile money, som betales uden for systemet.',
