'Pg_Bkash_Help' => 'Bruger bKash Tokenized Checkout (merchant-loginoplysninger fra bKash-merchantportalen). Debiterer i BDT. Checkout tilbyder bKash, så snart alle fire loginoplysninger er gemt.',
