'Pg_Paymob_Currency_Help' => 'Skal matche din Paymob-kontos valuta (EGP, SAR, AED, PKR eller OMR) og din butiks basisvaluta.',
'Pg_Paymob_Help' => 'Bruger Paymob Unified Checkout (kort, wallets og lokale metoder i Egypten, KSA, UAE, Pakistan og Oman). Alle fem loginoplysninger findes i Paymob Dashboard → Settings → Account Info + Payment Integrations.',
'Pg_Paymob_Webhook_Help' => 'Webhooken angives automatisk pr. betaling — ingen opsætning i dashboardet er nødvendig. Callback-URL som sikkerhedsnet til reference:',
