'Pg_Myfatoorah_Currency_Help' => 'Skal matche din MyFatoorah-kontos valuta (KWD, SAR, AED, QAR, BHD, OMR, JOD, EGP…) og din butiks basisvaluta.',
'Pg_Myfatoorah_Sandbox_Help' => 'TIL bruger apitest.myfatoorah.com med et demo-API-token; slå FRA for at debitere rigtige kunder via live-API\'et.',
'Pg_Myfatoorah_Help' => 'Hostet fakturalink med KNET, mada, kort, Apple Pay og STC Pay i hele GCC. API-tokenet findes i MyFatoorah Vendor Portal → Integration Settings → API Key.',
