'Pg_Xpay_Help' => 'Kortoplysninger indtastes i et XPay-element, der er indlejret på checkout-siden (ingen omdirigering). Hver betaling verificeres igen på serveren, før ordren oprettes. Bemærk: XPay\'s SDK kræver API HMAC-hemmeligheden i browseren, ligesom i XPay\'s officielle plugins.',
