'Shp_Cc_Alert' => 'Siden januar 2026 opretter Shopify ikke længere custom apps i administrationen. Opret appen i {dashboard}, giv den Admin API-scopes, installer den på denne butik, og kopiér derefter Client ID og Client secret fra dens {settings}-side. ERP-systemet henter selv et nyt adgangstoken hver 24. time. Appen og butikken skal tilhøre den samme Shopify-organisation.',
