'Shp_Domain_Change_Warning' => 'Hvis du gemmer et andet domæne, slettes alle posttilknytninger for denne forbindelse — de gemte id\'er tilhører den gamle butik.',
'Shp_ERP_Warehouse' => 'ERP-lager',
