'Shp_Create_Missing_Products' => 'Opret ERP-produkter for Shopify-produkter, der ikke matcher et SKU',
'Shp_Create_Missing_Customers' => 'Opret ERP-kunder for Shopify-kunder, der ikke matcher en e-mail',
'Shp_Create_Missing_Customers_Hint' => 'Når dette er slået fra, springes en ordre fra en ukendt kunde over i stedet for at blive gættet.',
'Shp_Entities_Lead' => 'Kun de enheder, der er slået til her, kan synkroniseres — en butik, du kun henter ordrer fra, skal ikke have en vildfaren produktoverførsel, der omskriver dens katalog.',
'Shp_Sync_On_Schedule' => 'Synkronisér automatisk efter en tidsplan',
'Shp_Scheduler_Hint' => 'Planlæggeren tjekker hvert 5. minut, hvilket er det fineste, intervallerne nedenfor kan bruge. Synkroniseringer kan altid startes manuelt.',
'Shp_Instant_Push_Hint' => 'Et salg, en retur eller en justering sender en lageroverførsel for netop de produkter i det øjeblik, den gemmes, så butikken er korrekt inden for sekunder i stedet for ved den næste planlagte kørsel. Intet andet at installere — overførslen kører, efter at salget er besvaret, så kassen aldrig venter på Shopify.',
'Shp_Switch_Inventory_First' => 'Slå først Lagerbeholdning til under {tab}.',
'Shp_Leave_Off_Lag' => 'Lader du det være slået fra, når et POS-salg først frem til Shopify ved den næste overførsel af lagerbeholdning — op til {n} minutter senere.',
'Shp_Default_Interval' => 'Standardinterval (minutter)',
'Shp_Default_Interval_Hint' => 'Bruges af alle trin, der ikke angiver deres eget.',
'Shp_What_Runs_Auto' => 'Hvad der kører automatisk',
'Shp_Plan_Hint' => 'Hvert trin er én enhed i én retning. Ordrer kommer altid kun {from} Shopify.',
