'Shp_Using_Default_Plan' => 'Bruger standardplanen',
'Shp_Default_Plan_Desc' => 'Ordrer hentes ind, og lager sendes ud, hvert {n}. minut. Tilføj et trin for at vælge selv — hvis du rydder listen igen, gendannes denne standard.',
'Shp_N_Min' => '{n} min',
'Shp_Step_Entity_Off' => '{entity} er slået fra på den forrige fane — dette trin springes over.',
'Shp_Inactive_Lc' => 'inaktiv',
'Shp_No_Locations' => 'Butikken rapporterer ingen lokationer',
'Shp_Could_Not_Load_Locations' => 'Kunne ikke indlæse lokationer — tjek forbindelsen først',
'Shp_Store_Updated' => 'Butik opdateret',
'Shp_Store_Connected' => 'Butik forbundet',
'Shp_Could_Not_Save_Store' => 'Kunne ikke gemme denne butik',
'Shp_G_Lead_Store' => 'Hvad denne butik har brug for for at holde sig synkroniseret. Alt her er specifikt for denne butik — webhook-URL\'en og id\'erne er de rigtige.',
'Shp_G_Lead_Store_Cmd' => 'Hvad denne butik har brug for for at holde sig synkroniseret. Alt her er specifikt for denne butik — webhook-URL\'en og id\'erne er de rigtige, så kommandoerne kan kopieres direkte over på serveren.',
'Shp_G_Lead_Generic' => 'Sådan holder en Shopify-butik sig synkroniseret med ERP-systemet. Vælg en butik ovenfor for at se dens egen tilstand, eller læs det, som det er — webhook-URL\'en er den samme, uanset hvilken butik du forbinder.',
'Shp_G_Lead_Generic_Cron' => 'Sådan holder en Shopify-butik sig synkroniseret med ERP-systemet. Vælg en butik ovenfor for at se dens egen tilstand, eller læs det, som det er — webhook-URL\'en og cron-linjen er de samme, uanset hvilken butik du forbinder.',
'Shp_G_Ways_Note' => 'De fleste butikker bruger begge: Den første holder butikken opdateret minut for minut, den anden fanger det, den første gik glip af — en webhook, der aldrig kom frem, en ændring foretaget direkte i Shopify-administrationen, en nat hvor webstedet var nede.',
'Shp_G_Both_Need' => 'Begge metoder kræver dette først',
'Shp_G_Credentials' => 'Shopify-loginoplysninger',
'Shp_G_Cred_Intro' => 'Siden januar 2026 opretter Shopify ikke længere custom apps i administrationen, så der findes to slags forbindelser:',
'Shp_G_Cred_Dev' => '{app} (alle butikker, der forbindes nu) — {path}. Giv de Admin API-scopes, som denne butik synkroniserer, installer appen på butikken, og kopiér derefter {clientId} og {clientSecret} fra appens Settings-side til {edit}. ERP-systemet veksler dem selv til et adgangstoken og fornyer det, før det udløber, hver 24. time. Client secret signerer også webhooks, så der kræves ikke andet. Appen og butikken skal høre til den samme Shopify-organisation.',
'Shp_G_Dev_App' => 'Dev Dashboard-app',
'Shp_G_Cred_Legacy' => '{app} (oprettet i administrationen før 2026) — fortsætter uændret med sit {token} ({prefix}) og sin {secret} som signeringshemmelighed til webhooks. Det er ikke den samme værdi som tokenet, og at bytte rundt på dem er den sædvanlige årsag til, at webhooks afvises.',
'Shp_G_Legacy_App' => 'Ældre custom app',
'Shp_G_Api_Secret_Key' => 'API secret key',
'Shp_G_Stored' => 'gemt',
'Shp_G_Missing_Refused' => 'mangler — leveringer vil blive afvist',
'Shp_G_Targets' => '{path} Det ERP-lager, hvis lagerbeholdning denne butik sælger, og den Shopify-lokation, som lagerbeholdningen skrives til. Synkronisering af lagerbeholdning og import af ordrer nægter begge at køre uden dem.',
'Shp_G_Currently' => 'Aktuelt: lager {warehouse}, lokation {location}',
'Shp_G_Not_Set_Lc' => 'ikke angivet',
'Shp_G_Ready' => 'klar',
'Shp_G_Incomplete' => 'ufuldstændig',
'Shp_G_Manual_Syncs' => 'Synkroniseringer, du starter manuelt',
'Shp_G_Manual_Body' => 'En synkronisering, der startes fra {centre}, svarer med det samme og kører i baggrunden i korte bidder, der hver fortsætter, hvor den forrige slap. Et stort katalog afbrydes aldrig halvvejs af en webanmodning, der løber tør for tid, og det stopper den ikke at lukke siden.',
'Shp_G_Worker_Managed' => 'Din platform kører workeren til det, så der er intet at installere.',
'Shp_G_Worker_Cron' => 'Workeren til det er endnu en cron-linje:',
'Shp_G_Cron_Copied' => 'Cron-linje kopieret',
'Shp_G_Worker_Busy' => 'Hvis workeren er optaget, fører den åbne side i Synkroniseringscenter selv kørslen videre efter nogle sekunder, én kort anmodning ad gangen — så en synkronisering altid bliver færdig, mens du ser på.',
'Shp_G_Pick_How' => 'Vælg derefter, hvordan den holder sig synkroniseret',
'Shp_G_Right_Away' => 'Med det samme',
'Shp_G_Stock_Live' => 'lager live',
'Shp_G_Stock_Not_Live' => 'lager ikke live',
'Shp_G_Realtime_Lead' => 'Hver ændring sendes, når den sker, inden for sekunder. To halvdele med hver sin kontakt: {webhooks} henter butikkens egne hændelser ind, og {push} sender lageret ud.',
'Shp_G_Webhooks_Lc' => 'webhooks',
'Shp_G_Instant_Push_Lc' => 'øjeblikkelig lageroverførsel',
'Shp_G_Webhooks_Heading' => 'Webhooks — butikken → ERP-systemet',
'Shp_G_Webhooks_Body' => 'Ordrer, ændringer af ordrestatus samt ændringer af produkter, kunder og lager foretaget i Shopify. Åbn butikken, og tryk på {button} på dens {tab} — det er sikkert at trykke to gange. Shopify sender til:',
'Shp_G_Webhooks_Tab' => 'Webhooks-fane',
'Shp_G_Webhooks_Note' => 'Adressen skal kunne nås fra internettet via HTTPS — Shopify leverer ikke til {localhost} eller et {test}-domæne. Hver levering registreres kun én gang, så Shopifys genforsøg ikke kan oprette en dubleret ordre, og en mislykket levering kan afspilles igen. Leveringer afvises, indtil signeringshemmeligheden fra trin 1 er gemt.',
'Shp_G_Push_Heading' => 'Øjeblikkelig lageroverførsel — ERP-systemet → butikken',
'Shp_G_People_Miss' => 'Det er denne indstilling, folk overser',
'Shp_G_Push_P1' => 'Et POS-salg når {not} frem til Shopify af sig selv. Er indstillingen slået fra, får butikken det først at vide ved næste trin, der sender lagerbeholdningen — og i det tidsrum kan den sælge en enhed, du allerede har solgt ved kassen.',
'Shp_G_Not' => 'ikke',
'Shp_G_Push_P2' => 'Sæt flueben ved {setting} under {path}. Det er hele opsætningen — ingen worker, ingen cron. Hvert salg, hver retur og hver justering sender derefter en overførsel af netop de produkter, lige efter at salget er gemt, og et salg med tyve linjer koster én overførsel, ikke tyve. Kassen venter aldrig på den.',
'Shp_G_This_Store' => 'Denne butik:',
'Shp_G_Push_On' => 'til — lager sendes ved ændring',
'Shp_G_Push_Off' => 'fra — lager kun efter tidsplan',
'Shp_G_Push_Note' => 'Kun produkter, der allerede har en Shopify-tilknytning, og kun bevægelser på denne butiks lager sendes. Masseoperationer — sletning af et produkt, nulstilling af et lager — skriver lager uden at udløse en hændelse, hvilket er én grund til også at beholde det planlagte trin for lagerbeholdning.',
'Shp_G_Nothing_Else' => 'Intet andet at installere',
'Shp_G_Nothing_Else_Body' => 'Ingen af halvdelene kræver en køworker eller en cron-post. En indgående webhook håndteres i den anmodning, Shopify foretager; en udgående lageroverførsel kører i den samme proces, som betjente salget, {after} svaret er sendt tilbage — så kassen aldrig venter på Shopify, og en butik, der holder op med at svare, opgives efter ti sekunder og overlades til den næste planlagte overførsel af lagerbeholdning.',
'Shp_G_After' => 'efter',
'Shp_G_Exception' => 'Én undtagelse: En lagerændring foretaget af en baggrundsopgave har intet svar at komme efter, så den sættes i stedet i kø på {queue}.',
'Shp_G_Queue_Managed' => 'Din platform kører allerede en worker på den kø, så de bliver også sendt af sig selv.',
'Shp_G_Queue_Cron' => 'Hvis du også vil have dem sendt hurtigt, så tøm den kø:',
'Shp_G_On_Schedule' => 'Efter en tidsplan',
'Shp_G_On_Lc' => 'til',
'Shp_G_Off_Lc' => 'fra',
'Shp_G_Scheduled_Lead' => 'Alt kontrolleres igen med jævne mellemrum, i begge retninger. Langsommere end realtid, men det er det, der sender lager ud fra butikker, der ikke bruger øjeblikkelig overførsel, det, der fanger en mistet webhook, og den eneste måde at flytte et helt katalog på.',
'Shp_G_Nothing_To_Install' => 'Intet at installere',
'Shp_G_Managed_Body' => 'Planlæggeren køres for dig: Hvert femte minut spørger din platform hver butik, om et trin i dens plan skal køre, og kører dem, der skal. Der er ingen cron-post at tilføje og ingen server at vedligeholde.',
'Shp_G_Managed_Note' => 'Fem minutter er også den fineste opløsning, en plan kan bruge, fordi fem minutter er det korteste trininterval. Længere intervaller overholdes præcist — et trin sat til 30 minutter kontrolleres seks gange og kører én gang.',
'Shp_G_Cron_Entry' => 'Cron-posten',
'Shp_G_Cron_Body' => 'Intet planlagt kører uden den. Én linje, kun til dette modul — tilføj den ved siden af det, du ellers har valgt at planlægge:',
'Shp_G_Cron_Note' => 'Hvert femte minut er den fineste opløsning, en plan kan bruge, fordi fem minutter er det korteste trininterval. En grovere post bliver blot bunden — med {every15} kører et trin sat til 5 minutter hvert 15. minut. På Windows skal du bruge Task Scheduler: program {php}, argumenter {args}, startet i {path}.',
'Shp_G_Switch_On' => 'Slå det til, og vælg planen',
'Shp_G_Plan_Body' => '{path} Kontakten afgør, om planlæggeren overhovedet må handle; planen afgør, hvad den gør. Et {step} er én enhed i én retning med sit eget interval — {ex1}, {ex2}. Standardintervallet bruges af alle trin, hvis eget felt er tomt.',
'Shp_G_Step_Lc' => 'trin',
'Shp_G_Ex1' => 'Ordrer · Shopify → ERP hvert 15. min',
'Shp_G_Ex2' => 'Lagerbeholdning · ERP → Shopify hvert 30. min',
'Shp_G_Plan_Note' => 'Lad planen være tom, så henter butikken ordrer og sender lager med standardintervallet, hvilket er det, de fleste butikker ønsker. Ordrer kan kun hentes: Det er i Shopify, at en kunde afgiver dem.',
'Shp_G_Schedule_On' => 'tidsplan til',
'Shp_G_Schedule_Off' => 'tidsplan fra — kun manuelt',
'Shp_G_When_Runs' => 'Hvornår et trin faktisk kører',
'Shp_G_When_Body' => 'Et trin skal køre, når det samme trin senest {started} for længere tid siden end dets interval, aflæst fra kørselshistorikken. En synkronisering, du starter manuelt, udskyder altså den næste automatiske, og et trin, der bliver ved med at fejle, forsøges igen efter sit interval i stedet for ved hvert tik. Butikkens Oversigt viser hvert trins seneste kørsel, næste kørsel og årsagen til, at det er blokeret, når det er. Kør den første katalogoverførsel manuelt fra Synkroniseringscenter — først som en testkørsel — før du sætter den på en tidsplan.',
'Shp_G_Started_Lc' => 'startede',
'Shp_G_Where_Setting' => 'Hvor hver indstilling findes',
'Shp_G_Where_Note' => 'Alle disse findes på en eksisterende butik: {path}, derefter blyanten (eller {edit} på butikkens egen side).',
'Shp_G_Product_Images' => 'Produktbilleder',
'Shp_G_Img1' => 'Billeder sendes med produktet ved en {push} — først hovedbilledet, derefter galleriet og så ét pr. variant, der har sit eget, op til halvtreds.',
'Shp_G_Products_Push' => 'produktoverførsel',
'Shp_G_Img2' => 'En variants billede uploades sammen med produktet og bliver derefter {assigned}, hvilket er sådan, Shopify modellerer det: En variant peger på et af produktets billeder. En variant, der genbruger hovedbilledet, uploader det ikke to gange.',
'Shp_G_Assigned' => 'tildelt den pågældende variant',
'Shp_G_Img3' => 'Et billede, der er gemt som fil, bliver {uploaded} til Shopify, ikke linket, så det virker, selv når denne installation ikke kan nås fra internettet. Et billede, der er tilføjet som et indsat link, gives videre til Shopify som den URL, der skal være offentligt tilgængelig.',
'Shp_G_Uploaded' => 'uploadet',
'Shp_G_Img4' => 'De sendes kun igen, når de faktisk ændres — en overførsel, der kun ændrer en pris, lader butikkens billeder være, fordi afsendelse af dem erstatter hele sættet.',
'Shp_G_Img5' => 'Hvis du fjerner et billede i ERP-systemet, slettes det {not} i Shopify. Slet det også der, ellers bliver butikken ved med at vise det.',
'Shp_G_Commands' => 'Kommandoer, der er værd at kende',
'Shp_G_Command_Copied' => 'Kommando kopieret',
'Shp_G_Foot' => 'Hver synkronisering skriver til {logs}, og hver butiks Oversigt viser, hvornår hvert trin senest kørte, hvornår det skal køre næste gang, og hvad der blokerer det, når noget gør. Det er der, du skal kigge først, når en synkronisering ikke gjorde, hvad du forventede.',
'Shp_G_Covers' => 'Dækker',
'Shp_G_Speed' => 'Hastighed',
'Shp_G_Needs' => 'Kræver',
'Shp_G_Switched_On_At' => 'Slås til under',
'Shp_G_Way_Covers_Rt' => 'Ordrer og ændringer foretaget i Shopify; lager, der forlader ERP-systemet (et POS-salg, en retur, en justering)',
'Shp_G_Way_Covers_Sc' => 'Alt, i begge retninger — inklusive katalogoverførsler og alt, hvad den hurtige vej gik glip af',
'Shp_G_Seconds' => 'Sekunder',
'Shp_G_Way_Speed_Sc' => 'Trinnets interval (5 minutter til 7 dage)',
'Shp_G_Way_Needs_Rt' => 'En offentlig HTTPS-adresse og signeringshemmeligheden til indgående webhooks. Udgående lager kræver slet ingenting',
'Shp_G_Way_Needs_Sc' => 'Planlæggeren, hvert femte minut',
'Shp_G_Way_Switch_Sc' => '{path} plus planen',
'Shp_G_Scope_Orders' => '{a} ({b} for ordrer ældre end 60 dage)',
'Shp_G_Admin_Scopes' => 'Admin API-scopes',
'Shp_G_Setting' => 'Indstilling',
'Shp_G_Tab_In_Edit' => 'Fane i Rediger butik',
'Shp_G_Set1' => 'Client ID + secret eller adgangstoken, signeringshemmelighed, API-version',
'Shp_G_What1' => 'Loginoplysningerne fra Shopify-appen (Dev Dashboard eller ældre custom app).',
'Shp_G_Set2' => 'ERP-lager, Shopify-lokation',
