'Agt_Series' => 'Serier',
'Agt_Series_Hint' => 'AGT godkender én nummerserie pr. dokumenttype, år og forretningssted. Fakturaer kan ikke udstedes uden en aktiv serie for deres type og år.',
'Agt_Request_Series' => 'Anmod om serie hos AGT',
'Agt_Add_Series' => 'Tilføj eksisterende serie',
'Agt_Contingency' => 'Nødprocedure',
'Normal' => 'Normal',
'Agt_Corrects' => 'Korrigerer',
'Agt_Late' => '> 24 t',
'Agt_Check' => 'Tjek',
'Agt_Correct_Confirm' => 'Udsted en korrektion med et nyt nummer for dette afviste dokument?',
'Agt_Correct' => 'Korrigér',
'Agt_Guide_What_Title' => 'Hvad dette gør',
'Agt_Guide_What_Body' => 'Hvert afsluttet salg udstedes som en elektronisk AGT-faktura (FR, når det er betalt ved oprettelse, ellers FT), og hver modtaget returnering som en kreditnota (NC). Hvert dokument får det næste nummer i sin AGT-serie, signeres med din AGT-nøgle og sendes til AGT, som validerer det nogle minutter senere. Kvitteringen og PDF-fakturaen viser AGT-nummeret, sikkerhedsuddraget og en QR-kode.',
'Agt_Guide_Steps_Title' => 'Opsætning',
'Agt_Guide_Step_1' => 'Tilmeld dig e-fakturering (adesão) på Portal do Contribuinte, og download din private AGT-nøgle.',
'Agt_Guide_Step_2' => 'Indtast dit NIF, forretningssted og nøglen på fanen Konfiguration, vælg Homologação, gem, og brug Test forbindelse.',
'Agt_Guide_Step_3' => 'På fanen Serier skal du anmode om én serie pr. dokumenttype, du bruger (FR, FT, NC), for det aktuelle år.',
'Agt_Guide_Step_4' => 'Knyt dine IVA-satser til AGT-koder, og angiv fritagelseskoden for 0 %-linjer.',
'Agt_Guide_Step_5' => 'Slå modulet til under Systemindstillinger > Funktioner, lav et testsalg, og kontrollér, at det bliver gyldigt på fanen Dokumenter.',
'Agt_Guide_Step_6' => 'Når AGT godkender dig til produktion, skal du skifte til Produção og anmode om produktionsserier.',
'Agt_Guide_Note_1' => 'Et indberettet salg eller en indberettet returnering kan ikke længere redigeres eller slettes. Korrigér det med en salgsreturnering (kreditnota).',
'Agt_Guide_Note_2' => 'Dokumenter, som AGT afviser, korrigeres med et nyt nummer, der henviser til det afviste; det gamle nummer genbruges aldrig.',
'Agt_Guide_Note_3' => 'Offline POS-salg indberettes, når de synkroniseres. AGT pålægger sanktioner for dokumenter, der sendes mere end 24 timer for sent.',
'Agt_Guide_Note_4' => 'En linje kan ikke have både en produktskat og ordreskatten; AGT kræver én IVA-sats pr. linje. Forsendelse sendes som en fritaget linje.',
'Agt_Guide_Note_5' => 'AGT-totaler beregnes pr. linje og kan afvige fra Stocky-totalen med nogle få øre på grund af afrunding.',
