'Dgi_Guide_What_Title' => 'Hvad dette gør i dag',
'Dgi_Guide_What_Body' => 'Når modulet er slået til, viser kvitteringer og PDF-fakturaer sælgerens NIF, RCCM og Id. Nat., som kræves på en facture normalisée. Fuld certificering (DEF-nummer, tællere, godkendelseskode og QR-kode returneret af DGI) tilføjes, når e-MCF-udvikler-API\'et er tilsluttet.',
'Dgi_Guide_Steps_Title' => 'Sådan får du adgang til e-MCF',
'Dgi_Guide_Step_1' => 'Opret en konto med dit NIF på developper.dgirdc.cd, og anmod om adgang til e-MCF-testmiljøet.',
'Dgi_Guide_Step_2' => 'Download API-dokumentationen (ruter, DTO\'er, skattegrupper) og testlegitimationsoplysningerne.',
'Dgi_Guide_Step_3' => 'Send dem til din platformadministrator, så forbindelsen kan færdiggøres og testes.',
