'Comm_G_When_Intro' => 'Provisioner oprettes første gang, når et salg med status Afsluttet gemmes, et af disse steder:',
'Comm_G_When_Create' => 'Opret salg: når salget gemmes som Afsluttet.',
'Comm_G_When_Edit' => 'Rediger salg: når et afsluttet salg gemmes, genberegnes det helt forfra med dets aktuelle total, betalinger og sælger, inklusive provisioner, der var annulleret.',
'Comm_G_When_Pos' => 'POS: når et salg afsluttes, også en kladde, der afsluttes senere.',
'Comm_G_When_Payment' => 'Når der tilføjes en betaling til et afsluttet salg – det er det, der lader regler med Betalt beløb fange betalinger modtaget efter salget.',
'Comm_G_When_Cod' => 'Efterkrav via kurer: når de kontanter, kureren har opkrævet, registreres som en betaling på salget.',
'Comm_G_When_Not_Intro' => 'Disse opretter IKKE provisioner:',
'Comm_G_When_Not_Status' => 'Salg gemt som Afventer eller Bestilt. De begynder at optjene, når de redigeres og gemmes som Afsluttet.',
'Comm_G_When_Not_Before' => 'Salg gemt, før programmet eller reglen fandtes. De beregnes ikke i baggrunden. Åbner du et sådant salg i Rediger salg og gemmer det, beregnes det med de regler, der var aktive på salgsdatoen.',
'Comm_G_When_Not_Import' => 'Salg importeret fra en fil.',
'Comm_G_When_Not_Online' => 'Ordrer afgivet i webshoppen.',
'Comm_G_T_Statuses' => 'Provisionsstatusser',
'Comm_G_Meaning' => 'Hvad det betyder',
'Comm_G_S_Pending' => 'Netop beregnet ud fra et salg. Ingen har kontrolleret den endnu. Godkend eller annullér den i Provisionsrapport.',
'Comm_G_S_Approved' => 'Kontrolleret og accepteret. Den skyldes sælgeren og kan medtages i en Provisionskvittering. Hvis salget ændres, og beløbet ændres, går den tilbage til Afventer til ny gennemgang.',
'Comm_G_S_Paid' => 'Medtaget i en Provisionskvittering. Endelig: betalte provisioner ændres aldrig. Hvis salget ændres bagefter, tilføjes differencen som en separat Regulering.',
'Comm_G_S_Cancelled' => 'Udbetales ikke. Den forbliver annulleret, når der senere kommer betalinger eller returneringer. Gemmer du salget i Rediger salg, eller markerer du den i rapporten og klikker på Genberegn, beregnes den igen.',
'Comm_G_Field' => 'Felt',
'Comm_G_T_Programs' => 'Provisionsprogrammer',
'Comm_G_Programs_Body' => 'Et program er en samling regler, typisk ét pr. periode eller kampagne. En regel virker kun, mens dens program er Aktivt, og salgsdatoen ligger inden for programmets datoer. Flere programmer kan være aktive samtidig, og de gælder alle.',
'Comm_G_F_Program_Name' => 'Et hvilket som helst navn, der hjælper dig med at genkende programmet, f.eks. "Q4 2026" eller "Black Friday".',
'Comm_G_F_Program_Active' => 'Fjern markeringen for at sætte alle regler i programmet på pause på én gang. Provisioner, der allerede er oprettet, påvirkes ikke.',
'Comm_G_F_Program_From' => 'Salg dateret før denne dag ignoreres af programmet. Lad feltet være tomt for ingen startdato.',
'Comm_G_F_Program_To' => 'Salg dateret efter denne dag ignoreres af programmet. Lad feltet være tomt for et program uden slutdato.',
'Comm_G_T_Agents' => 'Sælgere',
'Comm_G_Agents_Body' => 'En sælger er den person, der optjener provision. En sælger behøver ikke at være bruger af systemet: eksterne henvisere eller forhandlere kan også være sælgere, og de optjener, hver gang de vælges på et salg.',
'Comm_G_F_Agent_Name' => 'Navnet, der vises på salg, i rapporten og på kvitteringer.',
'Comm_G_F_Agent_Code' => 'Valgfri reference, f.eks. et medarbejdernummer. Kan søges i listen over sælgere.',
'Comm_G_F_Agent_User' => 'Knytter sælgeren til en medarbejderbruger. Salg, som den bruger foretager (eller er valgt som ekspedient for i POS), krediteres derefter automatisk denne sælger.',
'Comm_G_F_Agent_Active' => 'Inaktive sælgere optjener intet på nye salg og forsvinder fra sælgervalgene. Deres tidligere provisioner bevares.',
'Comm_G_T_Rules' => 'Provisionsregler: alle felter forklaret',
'Comm_G_Rules_Body' => 'En regel bestemmer, hvor meget der betales på et salg. Brug feltet "Afprøv en regel" ovenfor til at tjekke en regel, før du gemmer den.',
'Comm_G_F_Rule_Program' => 'Det program, reglen hører til. Reglen virker kun, mens programmet er aktivt og inden for sine datoer.',
'Comm_G_F_Rule_Type' => 'Procent betaler en andel af grundbeløbet. Fast betaler samme beløb på hvert kvalificerende salg, uanset størrelse.',
'Comm_G_F_Rule_Source' => 'Det, procentsatsen beregnes af. Salg i alt er salgets samlede total. Betalt beløb er det, kunden havde betalt, da provisionen blev beregnet.',
'Comm_G_F_Rule_Value' => 'Procentsatsen (5 betyder 5%) eller det faste beløb, afhængigt af Type.',
'Comm_G_F_Rule_Min' => 'Valgfrit. Salg, hvis grundbeløb er under dette, optjener intet fra denne regel. Et salg, der præcis svarer til grænsen, optjener.',
'Comm_G_F_Rule_Cap' => 'Valgfrit. Det maksimale, denne regel kan betale på ét salg. Virker for både procentregler og faste regler.',
'Comm_G_F_Rule_Applies' => 'Alle sælgere: alle sælgere optjener på denne regel. Bestemt sælger: kun den sælger, du vælger. En regel for en bestemt sælger uden valgt sælger udbetaler aldrig til nogen.',
'Comm_G_F_Rule_Priority' => 'I et program, der er sat til "Kun reglen med højest prioritet giver provision", vinder den kvalificerende regel med det højeste tal, og de andre springes over. Ved lighed slår en regel for en bestemt sælger en regel for alle sælgere. I et program, der er sat til "Alle matchende regler giver provision", bestemmer Prioritet kun rækkefølgen.',
'Comm_G_F_Rule_Active' => 'Fjern fluebenet for at sætte netop denne regel på pause. Provisioner, den allerede har oprettet, påvirkes ikke.',
'Comm_G_T_Stacking' => 'Flere regler på ét salg',
'Comm_G_Stacking_Body' => 'Hvert program bestemmer, hvordan dets regler kombineres (indstillingen "Når flere regler matcher" på programmet).

Kun reglen med højest prioritet giver provision (standard for nye programmer): reglerne afprøves fra højeste Prioritet og nedefter, og den første, der kvalificerer sig til salget, udbetaler. En regel kvalificerer sig, når salget når dens minimumsgrænse, og resultatet er over 0. Det gør trin nemme: "7 % på salg af 10,000 eller mere" med prioritet 10 og "5 %" med prioritet 0. Vil du give Sara en særlig sats, så tilføj en regel for en bestemt sælger for hende med højere prioritet end reglen for alle sælgere.

Alle matchende regler giver provision: alle matchende regler udbetaler, og beløbene lægges sammen. En regel for alle sælgere på 3 % plus en regel for Sara som bestemt sælger på 2 % giver Sara 5 %.

Programmer er adskilt fra hinanden: hvert aktivt program udbetaler for sig, så et salg kan give provision fra både et basisprogram og et kampagneprogram på samme tid.',
'Comm_G_T_Paying' => 'Udbetaling til sælgere med provisionskvitteringer',
'Comm_G_Paying_Body' => 'Åbn Provisionskvitteringer, og klik på Opret. Vælg sælgeren: vedkommendes godkendte provisioner vises. Sæt flueben ved dem, du udbetaler; Beløb udfyldes med deres samlede beløb, og du kan justere det. Referencen udfyldes automatisk (CR-000001, CR-000002...), og du kan tilføje betalingsmetode, dato og en bemærkning.

Når kvitteringen gemmes, markeres de afkrydsede provisioner som Betalt og knyttes til kvitteringen. Kun godkendte provisioner kan udbetales, så godkend dem først i Provisionsrapporten.

Negative justeringer (penge, sælgeren har fået for meget udbetalt) vises også. Sæt flueben ved dem sammen med sælgerens næste provisioner, så de trækkes fra den udbetaling.

En kvittering er kun en registrering af udbetalingen: den opretter ikke en udgift og flytter ikke penge på dine konti. Hvis du registrerer udbetalinger i Udgifter eller Bogføring, så registrér dem også der.',
'Comm_G_T_Snapshot' => 'Når et salg ændres',
'Comm_G_Snapshot_Body' => 'Provisioner følger salget. Hver gang et salg med provisioner ændres, genberegnes de ud fra dets aktuelle tal: salgets total minus modtagne returneringer og det betalte beløb minus refunderinger.

Ubetalte provisioner (Afventer eller Godkendt) opdateres blot. En godkendt provision, hvis beløb ændres, går tilbage til Afventer, så nogen kontrollerer den igen. En provision, der ikke længere skyldes (salg slettet, fuldt returneret, sælger ændret), fjernes.

Betalte provisioner ændres aldrig. Forskellen bliver til en ny række med status Afventer, markeret som Justering: positiv, når der skyldes mere (f.eks. når resten af et salg med reglen Betalt beløb er blevet betalt), negativ, når sælgeren har fået for meget udbetalt (f.eks. efter en returnering). Godkend den, og medtag den på sælgerens næste kvittering.

Hver provision beholder reglens vilkår (type, sats, grænse, loft) fra det tidspunkt, hvor den først blev optjent. Hvis en regel senere ændres eller slås fra, prissættes ældre salg ikke om, når de genberegnes.',
'Comm_G_T_Permissions' => 'Hvem kan hvad',
'Comm_G_Permission' => 'Tilladelse',
'Comm_G_Lets_You' => 'Hvad den giver adgang til',
'Comm_G_P_View' => 'Se alle provisionssiderne: programmer, sælgere, regler, kvitteringer, rapporten og denne vejledning.',
'Comm_G_P_Add' => 'Oprette programmer, sælgere og regler samt registrere provisionskvitteringer (udbetale til sælgere).',
'Comm_G_P_Edit' => 'Redigere programmer, sælgere og regler samt godkende eller annullere provisioner i Provisionsrapporten.',
'Comm_G_P_Delete' => 'Slette programmer, sælgere og regler.',
'Comm_G_T_Faq' => 'Spørgsmål og svar',
'Comm_G_Q_Empty' => 'Jeg har sat det hele op, men Provisionsrapporten er tom.',
'Comm_G_A_Empty' => 'Kontrollér, at: salget blev gemt, efter reglen blev oprettet; salget er Afsluttet; salget har en sælger (valgt på salget, eller brugeren, der oprettede det, er knyttet til en sælger); programmet er aktivt, og salgsdatoen ligger inden for dets datoer; reglen er aktiv og gælder for den sælger; og salget er på eller over reglens minimumsgrænse. Kontrollér også rapportens datofilter: det filtrerer efter den dato, provisionen blev beregnet.',
'Comm_G_Q_Twice' => 'En sælger fik to provisioner på ét salg.',
'Comm_G_A_Twice' => 'To regler udbetalte: enten er programmet sat til "Alle matchende regler giver provision", eller reglerne ligger i to forskellige aktive programmer (hvert program udbetaler for sig). Sæt programmet til "Kun reglen med højest prioritet giver provision", hvis kun én skal udbetale. Hvis et salg gemmes igen, bliver en provision aldrig dobbelt.',
'Comm_G_Q_Rate' => 'Hvis jeg ændrer en regels sats, ændres gamle provisioner så?',
'Comm_G_A_Rate' => 'Nej. Hver provision beholder vilkårene fra den regel, den blev optjent under, også når salget genberegnes senere. Den nye sats bruges til provisioner, der optjenes fremover.',
'Comm_G_Q_Return' => 'Kunden returnerede varerne. Hvad sker der med provisionen?',
'Comm_G_A_Return' => 'Den reduceres automatisk. En modtaget returnering sænker salgets total, og en refundering sænker det betalte beløb. Hvis provisionen ikke er udbetalt endnu, opdateres den (eller fjernes ved en fuld returnering). Hvis den allerede er udbetalt, tilføjes en negativ justering, som trækkes fra sælgerens næste kvittering.',
'Comm_G_Q_Wrong_Agent' => 'Jeg har krediteret den forkerte sælger. Hvordan retter jeg det?',
'Comm_G_A_Wrong_Agent' => 'Redigér salget, vælg den rigtige sælger, og gem. Provisionerne flyttes til den rigtige sælger. Hvis den første sælger allerede har fået udbetalt, tilføjes en negativ justering for vedkommende.',
'Comm_G_Q_Inactive' => 'Hvad sker der, når jeg deaktiverer en sælger?',
'Comm_G_A_Inactive' => 'Vedkommende holder op med at optjene på nye salg og skjules i sælgervalgene. Eksisterende provisioner bevares, kan stadig godkendes og udbetales og følger stadig ændringer i salgene. Et salg, der blev gemt med den sælger valgt, skifter ikke over til en anden sælger.',
'Comm_G_Q_Partial' => 'Hvordan håndterer regler med Betalt beløb delbetalinger?',
'Comm_G_A_Partial' => 'Et ubetalt salg giver ingen provision. Provisionen oprettes, når der første gang modtages penge (ved betaling eller når en betaling tilføjes), og vokser, efterhånden som flere betalinger kommer ind. Hvis en del af den allerede er udbetalt, kommer resten som en positiv justering.',
'Comm_G_Q_Undo' => 'Kan jeg fortryde en udbetaling eller en annullering?',
'Comm_G_A_Undo' => 'En udbetaling: nej. Betalt er endeligt, og kvitteringer kan ikke redigeres eller slettes, så kontrollér de afkrydsede provisioner og beløbet, før du gemmer. En annullering: ja. Sæt flueben ved rækken i Provisionsrapporten, og klik på Genberegn, eller gem salget igen under Rediger salg.',
'Comm_G_Q_Dates' => 'Hvilken dato bruger programmets datoer?',
'Comm_G_A_Dates' => 'Salgets egen dato, ikke den dag, det blev gemt. Et salg dateret sidste måned bruger kun programmer, der var gyldige sidste måned.',
'Comm_G_When_Changes' => 'Derefter opdateres provisionerne automatisk ved enhver ændring af et salg, der allerede har provisioner: betalinger, der redigeres eller slettes, returneringer og refunderinger, status, der ændres fra Afsluttet, eller sletning af salget.',
'Comm_G_F_Program_Mode' => 'Hvad der sker, når flere regler i dette program matcher det samme salg. "Kun reglen med højest prioritet giver provision": reglerne afprøves fra højeste Prioritet og nedefter, og den første, der kvalificerer sig, udbetaler. "Alle matchende regler giver provision": de udbetaler alle, og beløbene lægges sammen.',
'Comm_G_Q_Mode_Old' => 'Jeg har angivet prioriteter, men reglerne lægges stadig sammen.',
'Comm_G_A_Mode_Old' => 'Det program er sat til "Alle matchende regler giver provision". Programmer, der blev oprettet, før denne indstilling fandtes, beholder den adfærd, så deres udbetalinger ikke ændres. Redigér programmet, og vælg "Kun reglen med højest prioritet giver provision".',
'Comm_G_Q_Negative' => 'Hvorfor er der en negativ provision?',
'Comm_G_A_Negative' => 'Det er en justering: sælgeren har fået mere udbetalt, end salget nu giver, på grund af en returnering, en refundering, en lavere total, en ændret sælger eller et slettet salg. Godkend den, og sæt flueben ved den på sælgerens næste kvittering, så den bliver trukket fra.',
'Comm_Rule_Mode' => 'Når flere regler matcher',
'Comm_Mode_Highest' => 'Kun reglen med højest prioritet giver provision',
'Comm_Mode_All' => 'Alle matchende regler giver provision (de lægges sammen)',
'Comm_Mode_Highest_Short' => 'Højest prioritet vinder',
'Comm_Mode_All_Short' => 'Reglerne lægges sammen',
'Comm_Mode_Highest_Help' => 'Reglerne afprøves fra højeste Prioritet og nedefter; den første, der kvalificerer sig til salget, udbetaler, og de andre springes over. Godt til trin, f.eks. 7 % over 10,000 med prioritet 10 og 5 % for alt andet med prioritet 0.',
'Comm_Mode_All_Help' => 'Alle regler, der matcher sælgeren, udbetaler på salget, så beløbene lægges sammen. Prioritet bestemmer kun rækkefølgen.',
'Comm_Priority_Help_Highest' => 'Dette program udbetaler kun den kvalificerende regel med højest prioritet. Giv denne regel en højere Prioritet end de regler, den skal vinde over. Ved lighed slår en regel for en bestemt sælger en regel for alle sælgere.',
'Comm_Priority_Help_All' => 'Dette program udbetaler alle matchende regler, så denne regel lægges oven i de andre. Prioritet bestemmer kun rækkefølgen.',
'Comm_Recalculate' => 'Genberegn',
'Comm_Recalculate_Help' => 'Beregner de afkrydsede rækkers salg igen ud fra deres aktuelle tal, inklusive provisioner, der er annulleret.',
'Comm_Adjustment' => 'Justering',
'Comm_Adjustment_Help' => 'En rettelse af en provision, der allerede er udbetalt, fordi salget er ændret efterfølgende. Et negativt beløb trækkes fra sælgerens næste kvittering.',
'Comm_Cancel_Confirm' => 'Annuller de valgte provisioner?',
'Comm_Cancel_Confirm_Help' => 'De bliver ikke udbetalt og forbliver annulleret, når der senere kommer betalinger eller returneringer. Hvis salget gemmes under Rediger salg, eller der klikkes på Genberegn, beregnes de igen.',
'Fashion_Tiles_Hint' => 'Tilføj dine egne felter (billede, titel og link) i stedet for de automatiske kategorifelter.',

