'Rst_Guide_Menu_3' => 'Et tilvalg kan forbruge en ingrediens: knyt "Ekstra ost" til dit produkt Ost, så trækker hvert tilvalg på det lager.',
'Rst_Guide_Menu_4' => 'Markér en ret som udsolgt i dag med én kontakt; den kommer automatisk tilbage i morgen. Måltider (morgenmad, frokost, aftensmad) begrænser, hvornår en ret tilbydes.',
'Rst_Guide_Menu_5' => 'En opskrift er et kombiprodukt: med virtuel kombi-lagerbeholdning slået til trækker salg af retten komponenterne fra lageret.',
'Rst_Guide_Kitchen' => 'Køkkenskærm',
'Rst_Guide_Kitchen_1' => 'Åbn Restaurant › Køkken på en skærm i køkkenet. Vælg stationen; retter uden station vises på alle stationer.',
'Rst_Guide_Kitchen_2' => 'Bonner bliver orange og derefter røde, mens de venter (Restaurantindstillinger › forsinket efter N minutter). Et bip annoncerer nye bonner.',
'Rst_Guide_Kitchen_3' => 'Start → afkryds retter → Afslut. "Færdig ved denne station" afslutter kun denne stations retter på en fælles bon.',
'Rst_Guide_Kitchen_4' => 'Serverede bonner bliver vist i 15 minutter, så en fejl kan hentes tilbage. Bonner kan udskrives på en 80 mm-printer.',
'Rst_Guide_Kitchen_5' => 'Ordrer fra onlinebutikken og fra bord-QR-koder er markeret "Online" eller "QR" på deres bon.',
'Rst_Guide_Bills' => 'Regninger og betalinger',
'Rst_Guide_Bills_1' => 'Hver betaling er et almindeligt POS-salg: lager, kasse, bogføring, loyalitetspoint og e-fakturering fungerer som i POS.',
'Rst_Guide_Bills_2' => 'Servicegebyr er en procentdel af retterne før moms, for spisning på stedet (eller alle ordrer, afhængigt af din indstilling). Drikkepenge er en forudindstillet procentdel eller et beløb.',
'Rst_Guide_Bills_3' => 'En rabat kræver tilladelsen "Restaurantrabatter" og er begrænset af den største rabat i Restaurantindstillinger.',
'Rst_Guide_Bills_4' => 'Afrunding sker nedad til dit interval, til gæstens fordel, på den betaling, der afregner regningen.',
'Rst_Guide_Bills_5' => 'Del ligeligt: ét salg, én betalingslinje pr. person (andele fordelt helt præcist). Del pr. vare: hver gæsts retter bliver deres eget salg; vælg en plads for at vælge dens retter.',
'Rst_Guide_Bills_6' => 'Hvis regningen er ændret, efter den blev vist (en ret tilføjet fra en QR-kode, ændrede drikkepenge), afvises betalingen, så gæsten aldrig opkræves for noget, de ikke har set.',
'Rst_Guide_Bills_7' => 'Betalte retter kan ikke annulleres. Hvis den ubetalte rest af en bestilling annulleres, lukkes bestillingen som betalt, og bordet kan ryddes.',
'Rst_Guide_Bookings' => 'Reservationer og venteliste',
'Rst_Guide_Bookings_1' => 'Reservationer holder et bord i deres varighed (standard i Restaurantindstillinger). To reservationer kan aldrig overlappe på samme bord.',
'Rst_Guide_Bookings_2' => 'Bordplanen viser hvert bords næste reservation og advarer, når den snart begynder; "De er her — placér" placerer selskabet.',
'Rst_Guide_Bookings_3' => 'Efter udeblivelsestiden kan et forsinket selskab markeres som udeblevet; en fejl kan fortrydes.',
'Rst_Guide_Bookings_4' => 'Ventelisten holder gæster uden reservation i rækkefølge med deres oplyste ventetid. Ring eller skriv på WhatsApp til dem, når et bord er klar, og placér dem.',
'Rst_Guide_Bookings_5' => 'Onlinereservationer ankommer som "Reserveret" (et badge i sidemenuen tæller dem), så du kan bekræfte dem.',
'Rst_Guide_Online' => 'Onlineordrer, QR-menukort og onlinereservation',
'Rst_Guide_Online_1' => 'Med Restaurant-butikstemaet er onlinebutikkens forside dit menukort med tilvalg og kostfiltre; kunderne betaler ved kassen som normalt.',
'Rst_Guide_Online_2' => '"Onlineordrer til køkkenet" bestemmer, hvornår de når køkkenskærmen: når de afgives (betalt, eller en logget ind kunde, der betaler ved levering/afhentning), når de accepteres, eller aldrig.',
'Rst_Guide_Online_3' => 'Bord-QR-koder (Bordopsætning › Bord-QR-koder) åbner menukortet for det pågældende bord. "Nyt link" gør en udskrevet kode ugyldig.',
'Rst_Guide_Online_4' => 'QR-ordrer venter på bordets bestilling, indtil en tjener sender dem, medmindre "Send QR-ordrer direkte til køkkenet" er slået til. Gæster betaler hos personalet.',
'Rst_Guide_Online_5' => 'Onlinereservation tilbyder kun tidspunkter, hvor et bord, der passer til selskabet, er ledigt i hele reservationens varighed, og begrænser hvert telefonnummer til 3 kommende reservationer.',
'Rst_Guide_Online_6' => 'Alt dette er en del af onlinebutikken: den skal være slået til og indgå i dit abonnement.',
'Rst_Guide_Reports' => 'Overblik og rapporter',
'Rst_Guide_Reports_1' => 'Overblikket viser i dag sammenlignet med samme dag sidste uge: salg, regninger, gæster, gennemsnitlig regning, annulleringer og rabatter samt hvad der sker lige nu.',
'Rst_Guide_Reports_2' => 'Salg er restaurantregninger plus onlineordrer, der nåede køkkenet. Retsalg og avancer er før moms og bruger hvert produkts kostpris.',
'Rst_Guide_Reports_3' => 'Rapporter: salg pr. dag og betalingsmetode, retter, annulleringer og aflysninger (med begrundelser), personale, køkkentider og reservationer — alle kan eksporteres til Excel.',
'Rst_Guide_Reports_4' => 'Personale, der er begrænset til bestemte afdelinger, ser kun deres egne afdelinger; ordrer uden afdeling deles af alle.',
'Rst_Guide_Faq' => 'Godt at vide',
'Rst_Guide_Faq_1_Q' => 'En takeaway blev betalt, før jeg trykkede på "Send". Bliver den tilberedt?',
'Rst_Guide_Faq_1_A' => 'Ja. Betalingen sender alle retter, der endnu ikke er sendt, til køkkenet.',
'Rst_Guide_Faq_2_Q' => 'Hvorfor kan jeg ikke rydde et bord?',
'Rst_Guide_Faq_2_A' => 'Bestillingen har stadig ubetalte retter. Modtag betalingen, annullér det, der ikke blev spist, eller annullér hele bestillingen (kun når intet er betalt endnu).',
'Rst_Guide_Faq_3_Q' => 'To borde blev skubbet sammen. Hvad sker der med deres bestillinger?',
'Rst_Guide_Faq_3_A' => '"Sammenføj borde" flytter det andet bords retter (og eventuelle betalinger) over på hovedbordets bestilling; "Adskil" deler bordene igen.',
'Rst_Guide_Faq_4_Q' => 'Kan kortbetalinger bruge Stripe her?',
'Rst_Guide_Faq_4_A' => 'Nej. Stripe-kortbetalinger kræver POS-kortformularen; til en kortterminal skal du tilføje en betalingsmetode som "Kort" og bruge den på regningen.',
'Rst_Guide_Faq_5_Q' => 'En ret er kun udsolgt på lageret i én afdeling.',
'Rst_Guide_Faq_5_A' => 'Lageret trækkes fra bestillingens afdeling (bordets område, ellers standardafdelingen i Restaurantindstillinger). Brug "Udsolgt i dag" for hurtigt at stoppe bestillinger.',
'Rst_Guide_Faq_6_Q' => 'Skal jeg bruge en printer?',
'Rst_Guide_Faq_6_A' => 'Nej. Regninger, kvitteringer og køkkenbonner udskrives fra browseren på enhver printer; 80 mm-bonprintere passer bedst.',
'Rst_Guide_Faq_7_Q' => 'Hvor kommer restaurantens menukort i onlinebutikken fra?',
'Rst_Guide_Faq_7_A' => 'Fra de samme produkter, kategorier og tilvalg. Produkter, der er skjult fra onlinebutikken, og kategorier, der ikke vises i butikken, holdes ude af onlinemenukortet og QR-menukortet.',

