'Bkm_Guide_Customers_4' => 'Indloggede butikskunder finder deres bookinger under Min konto.',
'Bkm_Guide_Roles' => 'Hvem må hvad',
'Bkm_Guide_Roles_Help' => 'Giv hver rolle kun de tilladelser, den har brug for (Indstillinger › Gruppetilladelser).',
'Bkm_Guide_Job' => 'Job',
'Bkm_Guide_Give' => 'Giv dem',
'Bkm_Guide_Job_Front_Desk' => 'Reception',
'Bkm_Guide_Job_Staff_Member' => 'Medarbejder',
'Bkm_Guide_Job_Manager' => 'Leder',
'Bkm_Guide_Job_Owner' => 'Ejer eller bogholder',
'Bkm_Guide_Faq' => 'Spørgsmål',
'Bkm_Guide_Faq_1_Q' => 'Hvorfor vises en service ikke på hjemmesiden?',
'Bkm_Guide_Faq_1_A' => 'Den kræver bookingoplysninger (Services), at "Vis på hjemmeside" er slået til, at produktet er aktivt, og — for at kunne vælge et tidspunkt — en medarbejder, der kan bookes online og udfører den.',
'Bkm_Guide_Faq_2_Q' => 'Hvorfor er der ingen ledige tider?',
'Bkm_Guide_Faq_2_A' => 'Tjek medarbejdernes arbejdstider, fridage, helligdage og godkendt fravær, varslingstiden og hvor mange dage frem kunderne kan booke.',
'Bkm_Guide_Faq_3_Q' => 'Kan to kunder få samme tidspunkt?',
'Bkm_Guide_Faq_3_A' => 'Nej. Tidspunktet tjekkes igen, når de booker, og en reserveret eller bekræftet booking blokerer det. Hold deler pladser op til deres grænse.',
'Bkm_Guide_Faq_4_Q' => 'Hvad sker der, når en reservation udløber?',
'Bkm_Guide_Faq_4_A' => 'Tidspunktet bliver ledigt for andre igen. Bookingen bliver i Forespørgsler, indtil du besvarer den (eller annulleres, hvis depositum ikke blev betalt).',
'Bkm_Guide_Faq_5_Q' => 'Skal kunderne have en konto?',
'Bkm_Guide_Faq_5_A' => 'Nej. De får et privat link til deres bookingside. Butiks- og portalkonti viser også deres bookinger.',
'Bkm_Guide_Faq_6_Q' => 'Hvor går pengene hen?',
'Bkm_Guide_Faq_6_A' => 'Depositum går til din betalingsudbyder; resten opkræves i POS, når du opkræver bookingen. Rapporterne medregner omsætningen fra disse salg.',
'Bkm_Guide_Faq_7_Q' => 'Hvorfor fik en kunde ikke en e-mail?',
'Bkm_Guide_Faq_7_A' => 'Åbn bookingen: dens beskedliste viser, om hver e-mail blev sendt, fejlede eller blev sprunget over, og hvorfor.',
'Bkm_Staff_Removed' => 'fjernet',
'Bkm_Staff_Not_Bookable' => 'Kan ikke længere bookes',
'Bkm_Requests_Cut' => 'Viser de ældste {n}. Besvar nogle for at se resten, eller søg.',

