'Mkg_Guide_Faq_1_Q' => 'Min kampagne bliver ved med at stå på Sender, og intet bliver sendt.',
'Mkg_Guide_Faq_1_A' => 'Baggrundsafsenderen har ikke taget den op. Efter 30 minutter uden fremskridt vises knappen Send nu igen: klik på den for at genoptage. Hvis det bliver ved med at ske, så bed din platformadministrator om at tjekke, at baggrundsjobs (queue worker) kører.',
