'Mkg_Guide_Faq_6_A' => 'Nej. Kampagner, der sendes eller er sendt, er låst; opret i stedet en ny kampagne.',
'Mkg_Guide_Faq_7_Q' => 'Mine WhatsApp-beskeder kommer ikke frem.',
'Mkg_Guide_Faq_7_A' => 'Mere end 24 timer efter, at en kunde sidst skrev til dig, leverer WhatsApp kun skabeloner godkendt af Meta. Brug WhatsApp Cloud API, og vælg en godkendt skabelon i kampagnen.',
'Mkg_Guide_Faq_8_Q' => 'Hvis jeg sender en kampagne igen, får kunderne den så to gange?',
