'Pd_Guide_How_Title' => 'Sådan fungerer det',
'Pd_Guide_How_Intro' => 'En POS-enhed er en kortterminal eller et fiskalt kasseapparat ved kassen. Stocky sender beløbet til den, venter på, at kunden betaler, og registrerer først betalingen, når enheden har godkendt den.',
'Pd_Guide_Step_1' => 'Tilføj enheden her: model, lager og den betalingsmetode, som dens kortbetalinger registreres som (f.eks. "Kreditkort").',
'Pd_Guide_Step_2' => 'Vælg, hvordan Stocky når enheden: via en lokal bro på kassecomputeren eller via din udbyders cloud-API. Indtast de id\'er og nøgler, du har fået fra din bank eller udbyder.',
'Pd_Guide_Step_3' => 'Tryk på Test forbindelse. Bro-enheder skal testes fra den kassecomputer, broen kører på.',
'Pd_Guide_Step_4' => 'Vælg betalingsmetoden i POS, tryk på "Opkræv på enhed", og lad kunden betale. Salget kan gennemføres, når enheden har godkendt.',
'Pd_Guide_Step_5' => 'Se under Transaktioner efter kortbetalinger uden et salg (f.eks. en afbrudt betaling), og annuller eller refunder dem.',
'Pd_Guide_Bridge_Text' => 'Til enheder, der styres af et SDK fra leverandøren på kassecomputeren (USB-, seriel- eller LAN-parring). Browseren kan ikke bruge SDK\'et direkte, så et lille broprogram pakker det ind og lytter på denne computer.',
'Pd_Guide_Bridge_Point_1' => 'POS sender hver forespørgsel til bro-URL\'en fra kasserens browser; Stockys server behøver aldrig at nå dit butiksnetværk.',
'Pd_Guide_Bridge_Point_2' => 'Forespørgsler og svar signeres med den delte hemmelighed, så en godkendelse ikke kan forfalskes fra browseren.',
'Pd_Guide_Bridge_Point_3' => 'Installér og start broen på hver computer, der tager kortbetalinger på denne enhed.',
'Pd_Guide_Cloud_Text' => 'Til udbydere, der når enheden via internettet. Stockys server kalder API\'et, så intet skal installeres på kassecomputeren.',
'Pd_Guide_Cloud_Point_1' => 'API-URL\'en skal være https:// på en offentlig adresse.',
'Pd_Guide_Cloud_Point_2' => 'Mens kunden betaler, spørger Stocky om status hvert 2. sekund, så status-endpointet skal kunne finde betalingen ud fra dens reference; hvis API\'et svarer, før kortet er færdigt ("pending"), afgør forespørgslerne udfaldet.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'IDE280 er et fiskalt kasseapparat af den nye generation (YN ÖKC) med kortlæser. Den integreres normalt via Ingenicos ECR / GMP3 SDK eller via din banks integrationstjeneste.',
'Pd_Guide_Ide280_Point_1' => 'Par enheden med kassecomputeren som beskrevet i Ingenicos / bankens dokumentation, og peg derefter broen (eller API-indstillingerne) på den.',
'Pd_Guide_Ide280_Point_2' => 'Beløb sendes både som decimaltal og i kuruş (amount_minor) med valutaen TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Med "Fuld fiskal kvittering" får hver vare enhedens afdeling for sin momssats – tilpas momsafdelingerne til, hvordan enheden er programmeret.',
'Pd_Guide_Protocol_Title' => 'Bro- / API-kontrakt',
'Pd_Guide_Protocol_Intro' => 'Stocky taler JSON med broen eller API\'et. Stierne nedenfor er standard og kan ændres pr. enhed under Avanceret.',
'Pd_Guide_Operation' => 'Handling',
'Pd_Guide_Default_Endpoint' => 'Standard-endpoint',
