'Pd_Guide_When_Status' => 'Hvert 2. sekund, mens betalingen afventer.',
'Pd_Guide_When_Cancel' => 'Kassereren annullerer, mens der ventes på kortet.',
'Pd_Guide_When_Void' => 'Annullering af en betaling (samme dag, hele beløbet).',
'Pd_Guide_When_Refund' => 'Refundering af hele eller en del af en betaling.',
'Pd_Guide_Request_Title' => 'Forespørgsel',
'Pd_Guide_Request_Text' => 'Det indhold, Stocky sender ved et salg. Refundering og annullering medsender den oprindelige betaling som "original".',
'Pd_Guide_Response_Title' => 'Svar',
'Pd_Guide_Response_Text' => 'Feltnavne læses fleksibelt (også under "data"); "status" eller response_code "00" afgør udfaldet. Kortnumre gemmes maskeret.',
'Pd_Guide_Signing_Title' => 'Signering (bro)',
'Pd_Guide_Signing_Text' => 'Broen bør kontrollere Stockys signatur og skal signere sit nøjagtige svarindhold og returnere både "reference" og "operation" – usignerede svar eller svar om en anden handling afvises.',
'Pd_Guide_Browser_Title' => 'Browseradgang (bro)',
'Pd_Guide_Browser_Text' => 'POS-siden kalder broen fra browseren, så broen skal svare med disse CORS-headere (også ved OPTIONS-preflight).',
'Pd_Guide_Safety_Title' => 'Godt at vide',
'Pd_Guide_Safety_1' => 'Et salg gemmes kun med en godkendt enhedsbetaling på samme beløb; én enhedsbetaling kan aldrig betale to salg.',
'Pd_Guide_Safety_2' => 'Lukkes betalingsvinduet, efter at et kort er blevet trukket, annulleres trækket først.',
'Pd_Guide_Safety_3' => 'Hvis enheden ikke svarer i tide, vises betalingen som "Intet svar": tjek enheden, og annuller trækket under Transaktioner, hvis kortet blev trukket.',
'Pd_Guide_Safety_4' => 'Refunderinger og annulleringer her flytter kun penge på kortet; de ændrer ikke salget. Registrer returnerede varer under Salgsreturneringer.',
