'PartiallyPaid' => 'Delvist betalt',
'Ord_Guide_PayAuto_Tip' => 'Opdateres af sig selv, når der registreres betalinger på salget. Klik for at se, hvordan du registrerer en betaling.',
'Ord_Guide_PayAuto_Intro' => 'Denne kolonne viser, hvor meget af ordren der er betalt. Den tager udgangspunkt i kundens valg ved kassen og opdateres derefter af sig selv, efterhånden som der registreres betalinger på det salg, der oprettes, når ordren bekræftes. Den kan ikke redigeres fra denne side.',
'Ord_Guide_PayAuto_Paid' => 'Hele beløbet er modtaget. Hvis kunden betalte online via en betalingsgateway, opretter bekræftelsen af ordren salget som Betalt og registrerer betalingen for dig. Ellers skifter status til Betalt, når betalingerne på salget dækker totalen.',
'Ord_Guide_PayAuto_Partial' => 'Der er registreret en betaling på salget, men en del af totalen udestår stadig.',
'Ord_Guide_PayAuto_Pending' => 'Der er endnu ikke modtaget nogen betaling: efterkrav, bankoverførsel eller en anden metode med senere betaling. Bekræftelse af ordren opretter salget som Ubetalt, så du selv registrerer pengene, når du har modtaget dem. Se trinene nedenfor.',
'Ord_Guide_PayAuto_Note' => 'Betalingsstatus, der vises her, følger salget: den skifter af sig selv til Delvist betalt eller Betalt, når du gemmer en betaling, og skifter tilbage, hvis du sletter en. Salget er den regnskabsmæssige registrering, og det er det, der danner grundlag for dine betalings- og fortjenesterapporter. Brug Vis betalinger på salget for at gennemse eller redigere det, du har indtastet.',
