'Oc_G_T_Products' => 'Produkter',
'Oc_G_Products_1' => 'Et produkt matches ud fra sin kode her mod model og SKU i butikken. Tilknytningen huskes, så det ikke ødelægger den at omdøbe et produkt bagefter.',
'Oc_G_Products_2' => 'Når {company} sender et produkt, sætter den model, SKU, navn, pris, status og lager. Beskrivelse, billede og kategori skrives kun, når produktet er nyt i butikken eller ikke har nogen, så tekster skrevet i OpenCart bevares.',
'Oc_G_Products_3' => 'Et produkt, der er skjult i webshoppen eller ikke er til salg her, oprettes ikke i butikken; et allerede tilknyttet produkt sættes i stedet til deaktiveret der.',
'Oc_G_T_Variants' => 'Varianter og valgmuligheder',
'Oc_G_Variants_4' => 'OpenCart 4 har rigtige varianter (et produkt med valg af Farve og Størrelse), hver med sit eget lager. De svarer til dine varianter begge veje, og hver matches ud fra sin egen model.',
'Oc_G_Variants_3' => 'OpenCart 3 har ingen varianter, kun valgmuligheder, og lager pr. valgværdi. Et produkt med én valgmulighed (f.eks. Størrelse) synkroniseres med lager pr. værdi, som svarer til dine varianter. Et produkt med flere valgmuligheder får sine valgmuligheder oprettet uden lager pr. kombination: dets lager bliver på produktet som helhed, og dets salgslinjer kommer ind på produktet.',
'Oc_G_Variants_Multi' => 'Et butiksprodukt, der kun har valgmuligheder uden oprettede varianter, importeres som ét produkt; det noteres i logfilerne.',
'Oc_G_T_Stock' => 'Lager',
'Oc_G_Stock_1' => 'Med lagerkontakten slået til opdaterer hver bevægelse her (et salg, en returnering, et køb, en regulering, en overførsel) butikken inden for få sekunder, efter at siden har svaret, så kassereren aldrig venter på butikken.',
'Oc_G_Stock_2' => 'Én gang i timen tjekkes og rettes alle tilknyttede produkter, hvilket dækker masseændringer, som den direkte overførsel ikke kan se. Fanen Lager sender alt efter behov.',
'Oc_G_Stock_3' => 'Ydelser, produkter markeret som altid på lager og kombiprodukter med ubegrænsede komponenter vises som altid tilgængelige i butikken. Vælg et lager på fanen Forbindelse for kun at tælle det lager; ellers lægges alle lagre sammen.',
'Oc_G_T_Orders' => 'Ordrer og statusser',
'Oc_G_Orders_1' => 'En ny eller ændret ordre meldes straks af butikken og læses tilbage over den signerede forbindelse, så intet i selve beskeden stoles på. Hvert par minutter henter et tjek alt, hvad en besked har overset. Hver ordre bliver ét salg med referencen OC-<order number>; kunden matches ud fra e-mail eller oprettes.',
'Oc_G_Col_List' => 'Statusliste',
'Oc_G_Col_Meaning' => 'Hvad den gør her',
'Oc_G_Col_Default' => 'Sat ud fra din butik',
'Oc_G_Default_Commit' => 'De statusser, der trækker lager i OpenCart (som standard Pending, Processing, Shipped, Complete)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'Listerne udfyldes fra din butik ved første forbindelse og kan ændres på fanen Forbindelse. Hold den første liste ens med de statusser, der trækker lager i OpenCart, så begge sider flytter lager på samme trin.',
'Oc_G_Orders_3' => 'En ordre med en vare, der ikke matcher noget produkt, tilbageholdes, og produktet importeres fra butikken, hvis det findes der. Tilbageholdte ordrer forsøges igen ved hvert planlagt tjek; efter tolv forsøg logges de og lades ligge, så du kan hente dem manuelt.',
'Oc_G_T_Cancel' => 'Annulleringer og refusioner',
'Oc_G_Cancel_1' => 'Når en ordre får en annulleret status i butikken, tilbageføres salget her: lageret kommer tilbage, betalingerne fjernes, og salget slettes, præcis som hvis du slettede det på siden Salg.',
'Oc_G_Cancel_2' => 'Et salg, der allerede er leveret, har en returnering eller er godkendt af en skattemyndighed, tilbageføres aldrig af butikken. Det markeres i sine noter og i logfilerne, så du kan gennemgå det.',
'Oc_G_Cancel_3' => 'Hvis ordren genoprettes i butikken bagefter, kommer den ind igen som et nyt salg.',
'Oc_G_T_Automation' => 'Automatiseringskontakter',
'Oc_G_Auto_1' => 'Importér ordrer automatisk: ordrebeskeder og det planlagte tjek. Slået fra kommer ordrer kun ind, når du henter dem på fanen Ordrer.',
'Oc_G_Auto_2' => 'Send lager automatisk: direkte lageropdateringer og det timelige tjek. Slået fra ændres butikken kun, når du sender lager manuelt.',
'Oc_G_Auto_3' => 'Send produktændringer automatisk: et produkt, der oprettes eller redigeres her, opdaterer straks butikken. Slået fra bruger du fanen Produkter.',
'Oc_G_T_Faq' => 'Spørgsmål',
'Oc_G_Q_Secret' => 'Test forbindelse siger, at hemmeligheden ikke stemmer',
'Oc_G_A_Secret' => 'Åbn modulet {company} Connector i OpenCart, og kopiér hemmeligheden igen; et geninstalleret modul får en ny. Indsæt den på fanen Forbindelse, og gem, før du tester.',
'Oc_G_Q_Clock' => 'Test forbindelse siger, at butikkens ur går for meget forkert',
'Oc_G_A_Clock' => 'Signerede forespørgsler indeholder tidspunktet og afvises, når de to ure afviger med mere end fem minutter. Indstil dato og klokkeslæt på butikkens server.',
'Oc_G_Q_Redirect' => 'Test forbindelse siger, at butikken omdirigerer til en anden adresse',
'Oc_G_A_Redirect' => 'Din butik svarer på en anden adresse, typisk https i stedet for http eller med www. Brug adressen, der vises i meddelelsen, som butikkens URL.',
'Oc_G_Q_Not_Answering' => 'Test forbindelse siger, at connectoren ikke svarede',
'Oc_G_A_Not_Answering' => 'Adressen er ikke en OpenCart-butik, eller modulet er ikke installeret eller er deaktiveret. Tjek butikkens URL, og derefter at {company} Connector vises som installeret og aktiveret under Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Der afgives ordrer i butikken, men der går minutter, før de dukker op',
'Oc_G_A_No_Orders' => 'Butikken kan ikke nå dette arbejdsområde, så ordrer kommer kun ind via det planlagte tjek. Se på {company}-adressen på modulsiden: den skal kunne nås fra butikkens server. Kører du Test forbindelse, registreres den igen.',
'Oc_G_Q_Stock_Wrong' => 'Et antal i butikken er forkert',
'Oc_G_A_Stock_Wrong' => 'Send lager på fanen Lager, som genskriver alle tilknyttede produkter ud fra tallene her. Hvis det bliver ved med at skride, skal du tjekke, at lagerkontakten er slået til, og at ingen redigerer antal i OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'Et produkt vises som udsolgt i butikken, selvom der er lager her',
'Oc_G_A_Out_Of_Stock' => 'I OpenCart 3 har et produkt med flere valgmuligheder sit lager på produktet som helhed; tjek produktets antal i butikken frem for dets valgmuligheder. For alle produkter: send lager én gang, og se i logfilerne for det pågældende produkt.',
'Oc_G_Q_Held' => 'Logfilerne siger, at en ordre blev tilbageholdt',
'Oc_G_A_Held' => 'En af dens varer matcher ikke noget produkt her og kunne ikke importeres fra butikken, typisk fordi produktet er slettet der. Opret eller tilknyt produktet, og hent derefter ordrer på fanen Ordrer.',
'Oc_G_Q_Deleted_Sale' => 'Jeg slettede et importeret salg, og det kom tilbage',
'Oc_G_A_Deleted_Sale' => 'Så længe ordren er aktiv i butikken, importerer den næste besked eller det næste tjek den igen. Annuller i stedet ordren i butikken, hvilket tilbagefører salget her.',
'Oc_G_Q_Uninstall' => 'Hvordan afbryder jeg forbindelsen til butikken?',
'Oc_G_A_Uninstall' => 'Slå synkroniseringen fra på fanen Forbindelse; intet flyttes, mens den er slået fra. For at fjerne integrationen fra butikken skal du afinstallere {company} Connector under Extensions → Modules.',
'Oc_Full_Guide' => 'Åbn den fulde guide',
'Comm_Receipt_Account_Hint' => 'Den kasse- eller bankkonto, denne udbetaling går fra. Dens saldo falder med beløbet, og der bogføres Salgsprovision (Sales Commission Expense) mod den.',
'Comm_G_Q_Ledger' => 'Hvad gør en provisionsudbetaling i regnskabet?',
'Comm_G_A_Ledger' => 'Når du opretter en kvittering og vælger en konto, falder kontoens saldo med kvitteringens beløb, og hvis automatiske posteringer er slået til, bogføres en postering: debet Salgsprovision (Sales Commission Expense, 5200-COMM), kredit den valgte kasse- eller bankkonto. Er der ikke valgt nogen konto, krediteres standardkontoen Kasse (Cash), og ingen saldo ændres.',
'Hide_Zero_Decimals' => 'Skjul nuldecimaler',
'Sys_Hide_Zero_Decimals_Help' => 'Vis hele beløb uden decimaler: 100.00 bliver til 100, mens 100.50 beholder sine decimaler. Kun visning; gemte værdier og beregninger er uændrede.',
'Sys_Currency_Position_Before_NoSpace' => 'Før beløbet, uden mellemrum',
