'SW_Top_Up_Help' => 'Penge, der er betalt til leverandøren på forhånd. De trækkes fra den valgte konto og står i tegnebogen, indtil de bruges på køb.',
'SW_Refund_Help' => 'Leverandøren tilbagebetaler en del af forudbetalingen kontant. Beløbet trækkes fra tegnebogen og indsættes på den valgte konto.',
'SW_Adjust_Help' => 'Manuel rettelse uden pengebevægelse. En årsag er påkrævet og gemmes i kontokortet.',
