'Purchase_Update_Selling_Price' => 'Rediger salgspris ved køb',
'Sys_Purchase_Update_Selling_Price_Help' => 'Tilføjer et salgsprisfelt på hver købslinje ved siden af kostprisen. En pris, der indtastes der, erstatter produktets salgspris, når købet gemmes; lad feltet være tomt for at beholde den nuværende pris.',
'Current_Selling_Price' => 'Nuværende salgspris',
