'Selling_Price_In_Base_Currency' => 'Indtastes i basisvalutaen',
'Purchase_Update_Product_Cost' => 'Opdater produktets kostpris ved køb',
'Sys_Purchase_Update_Product_Cost_Help' => 'Når et modtaget køb gemmes, bliver hvert produkts kostpris lig med nettostykprisen på købslinjen (efter linjerabat, ekskl. moms, pr. basisenhed). Afventende og bestilte køb ændrer den ikke.',
'Show_Stock_In_Search_Results' => 'Vis lager i søgeresultater',
'Show_Stock_In_Search_Results_Help' => 'Vis hvert produkts disponible antal ved siden af det i POS-søgelisten.',
'Layout_6_Tabular' => 'Layout 6 - Tabel',
'Show_Signature_Line' => 'Vis underskriftslinje',
'Show_Signature_Line_Desc' => 'Udskriver en tom linje til kundens underskrift under kvitteringen, uanset hvilket layout der er valgt.',
'Customer_Signature' => 'Kundens underskrift',
'Set_Signature_Label' => 'Tekst ved underskriftslinje (tom = "Kundens underskrift")',
'Oc_Code_Source' => 'Kilde til produktkode',
'Oc_Code_Source_Help' => 'Hvilket OpenCart-felt der er produktkoden her. Model er påkrævet i OpenCart, så nogle butikker skriver en kategori eller produkttype i det og har den rigtige varekode i SKU, ISBN, UPC, EAN, JAN eller MPN; vælg det felt for sådan en butik. Model og derefter SKU bruges, når det valgte felt er tomt. Gælder for hentede produkter, matchning og afsendelser.',
'Oc_Code_Source_Model' => 'Model (standard)',
'Oc_Code_Source_Sku' => 'SKU',
'Oc_Connector_Link' => 'Connectorens websted',
'Oc_Connector_Link_Help' => 'Din webstedsadresse. OpenCart linker connectorens navn til den på siden Extensions > Installer. Lad feltet være tomt for at bruge adressen på dette {company}-arbejdsområde.',
'Store_Warehouses_Help' => 'Det lager, der vises og trækkes online, kommer fra disse lagre. Mens "Begræns produkter efter lager" er slået til under Funktioner, viser butikken også kun de produkter, der hører til (eller har lager i) disse lagre.',
'Oc_Code_Source_Needs_Update' => 'Den connector, der er installeret i butikken (version {version}), rapporterer kun Model og SKU. Download connectoren igen, og upload den oven i den gamle i butikken, så dette felt kan læses.',
'Oc_L_Title' => 'OpenCart-logfiler',
'Oc_L_Intro' => 'Hver produkthentning, afsendelse, lageropdatering, ordre og hvert butikskald registreres her. Filtrér på fejl for at se, hvad der mislykkedes, åbn en række for at læse, hvad den betyder, og hvad du skal gøre, og eksportér listen, når du skal sende den til support.',
'Oc_L_Tab_Hint' => 'Den fulde logside forklarer hver post, filtrerer efter handling og dato og eksporterer til en fil.',
