'Oc_L_H_Secret' => 'Den hemmelighed, der er gemt her, er ikke den, connector-modulet i OpenCart har, så butikken afviser alle kald.',
'Oc_L_F_Secret' => 'Åbn Extensions → Modules → connectoren i OpenCart, kopiér den viste hemmelighed, indsæt den på fanen Forbindelse, og gem. En geninstallation af modulet opretter en ny hemmelighed.',
'Oc_L_H_Clock' => 'OpenCart-serverens ur afviger for meget fra vores, så signerede forespørgsler ser udløbne ud.',
'Oc_L_F_Clock' => 'Bed hostingudbyderen om at indstille servertiden (NTP). Allerede en forskel på få minutter er nok til at blokere forbindelsen.',
'Oc_L_H_Disabled' => 'Connector-modulet er installeret i OpenCart, men slået fra.',
