'Oc_L_H_Model_Taken' => 'Et produkt, der er sendt til butikken, har en kode, som et andet butiksprodukt eller en af dets varianter allerede bruger som model.',
'Oc_L_F_Model_Taken' => 'Ret koden på det ene af de to produkter, eller hent produkter først, så det eksisterende butiksprodukt tilknyttes i stedet for at blive oprettet igen.',
'Oc_L_H_Model_Missing' => 'Et produkt, der er sendt til butikken, har ingen kode eller intet navn. OpenCart kræver begge dele.',
'Oc_L_F_Model_Missing' => 'Giv produktet en kode og et navn her, og send det igen.',
