'Oc_L_H_Review' => 'En ordre blev annulleret i OpenCart, efter at salget her var leveret eller returneret, så lageret blev ikke tilbageført automatisk.',
'Oc_L_F_Review' => 'Åbn salget, og beslut, om varerne skal returneres, eller om det skal blive, som det er.',
'Oc_L_H_Reversed' => 'En ordre blev annulleret i OpenCart, og det tilsvarende salg her blev tilbageført, så lageret blev lagt tilbage.',
'Oc_L_H_Backlog' => 'Den planlagte ordrehentning fandt flere ordrer, end den behandler i én kørsel, og fortsætter næste gang.',
'Oc_L_F_Backlog' => 'Hent ordrer manuelt fra fanen Ordrer for at afvikle efterslæbet.',
'Oc_L_H_Paused' => 'Automatiske afsendelser er sat på pause et stykke tid, fordi butikken holdt op med at svare. Ændringer foretaget i mellemtiden sendes, når den svarer igen.',
'Oc_L_F_Paused' => 'Tjek, at butikken er online. Andet er ikke nødvendigt; køen genoptages af sig selv.',
'Oc_L_H_Busy' => 'To automatiske afsendelser overlappede, og den ene trådte til side. Intet gik tabt.',
'Oc_L_H_Codes_Suffixed' => 'Nogle hentede produkter har en kode, som et andet butiksprodukt allerede havde her, typisk fordi det valgte kodefelt er tomt eller indeholder et kategorinavn. De blev oprettet med OpenCart-id\'et tilføjet, så to produkter ikke smelter sammen.',
'Oc_L_F_Codes_Suffixed' => 'Udfyld kodefeltet (Model, SKU, ISBN…) i OpenCart for produkterne nedenfor, eller vælg en anden Kilde til produktkode på fanen Forbindelse, og nulstil derefter produkttilknytningerne, og hent igen.',
'Oc_L_H_Options' => 'Nogle butiksprodukter har valgmuligheder (størrelse, farve…) uden variantlager, så lageret føres for produktet som helhed.',
'Oc_L_F_Options' => 'Intet er påkrævet. For at føre lager pr. valgmulighed skal du gøre valgmulighederne til varianter i OpenCart 4 eller bruge én valgmulighed pr. produkt i OpenCart 3.',
'Oc_L_H_Pull_Ok' => 'Denne side med produkter blev læst fra butikken. Oprettet betyder et nyt produkt her; opdateret betyder, at det allerede fandtes og blev tilknyttet.',
'Oc_L_H_Pull_Failed' => 'Nogle produkter på denne side kunne ikke gemmes her; hvert af dem står nedenfor med årsagen.',
'Oc_L_F_Pull_Failed' => 'Ret de angivne produkter i OpenCart (et manglende navn eller en manglende kode er den typiske årsag), og hent igen. Kun de mislykkede berøres.',
'Oc_L_H_Push_Warnings' => 'Produkterne blev sendt til butikken, men butikken rapporterede problemer med nogle af dem, f.eks. et billede, den ikke kunne hente.',
'Oc_L_F_Push_Warnings' => 'Læs listen nedenfor. Billeder skal kunne nås fra butikkens server; alt andet blev gemt, som det blev sendt.',
'Oc_L_H_Missing_Remote' => 'Lageret blev sendt, men nogle tilknyttede produkter findes ikke længere i butikken.',
'Oc_L_F_Missing_Remote' => 'Send produkter for at genoprette dem i butikken, eller nulstil produkttilknytningerne, hvis de blev slettet med vilje.',
'Oc_L_H_Generic' => 'Et synkroniseringstrin mislykkedes. Meddelelsen ovenfor er butikkens eller serverens egen begrundelse.',
'Oc_L_F_Generic' => 'Kør Test forbindelse på fanen Forbindelse. Hvis den lykkes, så prøv trinnet igen; hvis den mislykkes, så følg det tip, den giver.',
'Oc_L_H_Code_Fallback' => 'Nogle produkter på denne side kom uden en værdi i det felt, der er valgt som Kilde til produktkode, så deres Model (ofte et kategorinavn) blev brugt som kode.',
'Oc_L_F_Code_Fallback' => 'Tjek "Produkter med hvert felt" nedenfor. Hvis det valgte felt viser 0, selvom butikken har disse værdier, gemmer butikken dem under et andet id-navn; åbn et af de angivne produkter i OpenCart (fanen Data, Product Codes), og send os det, der vises. Ellers skal du udfylde feltet i OpenCart for de angivne produkter og hente igen.',
'Oc_L_H_Old_Connector' => 'Butikken kører stadig en connector, der er ældre end 1.1.0 og kun sender Model og SKU, så det valgte kodefelt kommer aldrig frem, og Model blev brugt.',
'Oc_L_F_Old_Connector' => 'Download connectoren igen, afinstallér og slet den gamle i OpenCart (Extensions → Installer), installér den nye, indsæt dens nye hemmelighed på fanen Forbindelse, og kør Test forbindelse. Siden skal vise Connector 1.1.0, før du henter.',
