'Trk_Tab' => 'Sporing og analyse',
'Trk_Intro' => 'Forbind Google Analytics, Google Ads, Google Tag Manager og Meta Pixel med din onlinebutik. Indsæt kun ID\'et, ikke kodestykket. Sidevisninger, produktvisninger, læg i kurv, checkout og køb sendes automatisk.',
'Trk_Google_Tag_ID' => 'Google tag-ID',
'Trk_Google_Help' => 'Google Analytics > Admin > Data streams (G-…), Google Ads > Tools > Google tag (AW-…) eller Tag Manager (GTM-…). For at tælle køb som en Google Ads-konvertering skal du tilføje konverterings-ID\'et med dets label, f.eks. AW-123456789/AbCdEf. Adskil flere ID\'er med kommaer.',
'Trk_Meta_Pixel_ID' => 'Meta Pixel-ID',
'Trk_Meta_Help' => 'Meta Events Manager > Data sources: nummeret, der vises under navnet på din Pixel. Adskil flere ID\'er med kommaer.',
'Trk_Consent_Note' => 'Cookiebanneret er slået til: Google Analytics og Tag Manager indlæses først, når en besøgende accepterer analysecookies, og Google Ads og Meta Pixel først, når vedkommende accepterer marketingcookies.',
